const rawStorage=(()=>{try{const x=window.localStorage;x.setItem('__bp_probe','1');x.removeItem('__bp_probe');return x}catch{let mem={};return {getItem:k=>Object.prototype.hasOwnProperty.call(mem,k)?mem[k]:null,setItem:(k,v)=>{mem[k]=String(v)},removeItem:k=>{delete mem[k]},clear:()=>{mem={}},key:i=>Object.keys(mem)[i]??null,get length(){return Object.keys(mem).length}}}})();
const AUTH_ACCOUNTS_KEY='bp-auth-accounts-v18',AUTH_SESSION_KEY='bp-auth-session-v18',AUTH_POLICY_KEY='bp-auth-policy-v19';
const SYNC_DEVICE_KEY='bp-device-v20',SYNC_META_KEY='bp-sync-meta-v20',SYNC_JOURNAL_KEY='bp-sync-journal-v20',SYNC_CHECKPOINTS_KEY='bp-sync-checkpoints-v20';
let syncMutationMuted=false;
const rawGet=(k,d)=>{try{return JSON.parse(rawStorage.getItem(k))??d}catch{return d}},rawSet=(k,v)=>{try{rawStorage.setItem(k,JSON.stringify(v))}catch{}};
function authAccounts(){return rawGet(AUTH_ACCOUNTS_KEY,[])}
function authSession(){return rawGet(AUTH_SESSION_KEY,null)}
function sessionPolicyFor(id){return(rawGet(AUTH_POLICY_KEY,{})||{})[id]||'never'}
function policyMs(policy){return policy==='12h'?43200000:policy==='24h'?86400000:policy==='7d'?604800000:0}
function activeAuthAccount(){const s=authSession();if(!s)return null;if(s.kind==='guest')return{id:'guest',name:'Guest',email:'Guest workspace',guest:true};const max=policyMs(sessionPolicyFor(s.accountId));if(max&&s.at&&Date.now()-new Date(s.at).getTime()>max){rawStorage.removeItem(AUTH_SESSION_KEY);return null}return authAccounts().find(a=>a.id===s.accountId)||null}
let activeAccount=activeAuthAccount();
const scopedKey=k=>`bp-user:${activeAccount?.id||'signedout'}:${k}`;
function currentDevice(){let d=rawGet(SYNC_DEVICE_KEY,null);if(!d){d={id:`device-${Date.now()}-${Math.random().toString(16).slice(2,10)}`,name:'This device',createdAt:new Date().toISOString(),lastSeenAt:new Date().toISOString()};rawSet(SYNC_DEVICE_KEY,d)}else{d.lastSeenAt=new Date().toISOString();rawSet(SYNC_DEVICE_KEY,d)}return d}
const syncDevice=currentDevice();
function rawScopedGet(suffix,d){try{return JSON.parse(rawStorage.getItem(scopedKey(suffix)))??d}catch{return d}}
function rawScopedSet(suffix,v){rawStorage.setItem(scopedKey(suffix),JSON.stringify(v))}
function recordSyncMutation(key,op,value=''){if(syncMutationMuted||!activeAccount||String(key).startsWith('bp-sync-'))return;const journal=rawScopedGet(SYNC_JOURNAL_KEY,[]);journal.unshift({id:`rev-${Date.now()}-${Math.random().toString(16).slice(2,7)}`,key,op,at:new Date().toISOString(),deviceId:syncDevice.id,size:String(value??'').length});rawScopedSet(SYNC_JOURNAL_KEY,journal.slice(0,250))}
const storage={getItem:k=>rawStorage.getItem(scopedKey(k)),setItem:(k,v)=>{rawStorage.setItem(scopedKey(k),v);recordSyncMutation(k,'set',v)},removeItem:k=>{rawStorage.removeItem(scopedKey(k));recordSyncMutation(k,'remove','')}};
