function accountId(){return activeAccount?.id||null}
function escapeAttrLocal(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fallbackDigest(s){let h1=0x811c9dc5,h2=0x9e3779b9;for(let i=0;i<s.length;i++){h1=Math.imul(h1^s.charCodeAt(i),0x01000193);h2=Math.imul(h2+s.charCodeAt(i),0x85ebca6b)}return `${(h1>>>0).toString(16)}${(h2>>>0).toString(16)}`}
function bytesToBase64(bytes){let s='';bytes.forEach(b=>s+=String.fromCharCode(b));return btoa(s)}
function base64ToBytes(s){try{return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}catch{return new Uint8Array()}}
async function passwordDigest(password,saltB64){try{if(globalThis.crypto?.subtle){const enc=new TextEncoder(),salt=base64ToBytes(saltB64),material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:120000,hash:'SHA-256'},material,256);return bytesToBase64(new Uint8Array(bits))}}catch{}return fallbackDigest(`${saltB64}|${password}`)}
function makeSalt(){try{const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return bytesToBase64(bytes)}catch{return fallbackDigest(`${Date.now()}-${Math.random()}`)}}
function makeAccountId(){try{return `acct-${crypto.randomUUID()}`}catch{return `acct-${Date.now()}-${Math.random().toString(16).slice(2)}`}}
function migrateLegacyInto(id,{includeGuest=false}={}){const keys=[];for(let i=0;i<rawStorage.length;i++){const k=rawStorage.key(i);if(k)keys.push(k)}keys.forEach(k=>{if(k.startsWith('bp-auth-')||k.startsWith('bp-user:')||k==='__bp_probe')return;if(!k.startsWith('bp-'))return;const dest=`bp-user:${id}:${k}`;if(rawStorage.getItem(dest)==null){const v=rawStorage.getItem(k);if(v!=null)rawStorage.setItem(dest,v)}});if(includeGuest){keys.filter(k=>k.startsWith('bp-user:guest:')).forEach(k=>{const suffix=k.slice('bp-user:guest:'.length),dest=`bp-user:${id}:${suffix}`;if(rawStorage.getItem(dest)==null){const v=rawStorage.getItem(k);if(v!=null)rawStorage.setItem(dest,v)}})}}
function seedAccountProfile(id,name){const key=`bp-user:${id}:bp-profile-v5`;let p={};try{p=JSON.parse(rawStorage.getItem(key)||'{}')||{}}catch{};if(!p.name&&name)p.name=name;if(!p.role||p.role==='Private · local workspace')p.role='Private Blueprint workspace';rawStorage.setItem(key,JSON.stringify(p))}
