document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p)go(p.dataset.page);const j=e.target.closest('[data-page-jump]');if(j)go(j.dataset.pageJump);const t=e.target.closest('[data-toast]');if(t)showToast(t.dataset.toast)});
$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');

