$('#themeBtn').onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;storage.setItem('bp-theme',next)};

function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),1800)}

function renderInbox(){const wrap=$('#inboxList');wrap.innerHTML=inbox.map((x,i)=>`<div class="inbox-row" data-inbox="${i}"><input type="checkbox" aria-label="Complete inbox item"><div class="item"><strong>${escapeHTML(x.title)}</strong><small>${escapeHTML(x.meta||'Captured')}</small></div><span class="pill">${x.type||'Inbox'}</span></div>`).join('')||'<div class="archive-empty" style="min-height:220px"><div><div class="glyph">✓</div><h3>No loose ends.</h3><p>No pinned follow-up is waiting to be clarified.</p></div></div>';$('#inboxCount')&&($('#inboxCount').textContent=inbox.length)}
function escapeHTML(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
renderInbox();
document.addEventListener('change',e=>{if(e.target.matches('.inbox-row input')){const row=e.target.closest('.inbox-row'),i=Number(row.dataset.inbox);row.style.opacity='.35';row.style.transform='translateX(4px)';setTimeout(()=>{inbox.splice(i,1);store.set('bp-inbox-v2',inbox);renderInbox();showToast('Loose end cleared')},260)}});

const modal=$('#captureModal'), modalBackdrop=$('#modalBackdrop');
function clearTypeFields(){$$('.type-fields').forEach(x=>x.style.display='none')}
function updateCaptureFields(){const type=$('#captureType').value;clearTypeFields();if(type==='Time block')$('#scheduleFields').style.display='grid';if(type==='Goal')$('#goalFields').style.display='block';if(type==='Experiment')$('#experimentFields').style.display='block';if(type==='Schedule')$('#recurringFields').style.display='block';if(type==='Memory')$('#memoryFields').style.display='block';if(type==='Metric')$('#metricFields').style.display='block';$('#notesLabel').textContent=type==='Experiment'?'Hypothesis':type==='Goal'?'Description':type==='Schedule'?'Intent / context':type==='Memory'?'What should Blueprint remember?':type==='Metric'?'Why is this signal useful?':'Notes';$('#captureHeading').textContent=$('#captureEditId').value?`Edit ${type.toLowerCase()}`:(type==='Inbox'?'Detailed capture':`New ${type.toLowerCase()}`)}
function resetCaptureExtras(){$('#captureEditId').value='';$('#goalKind').value='target';$('#goalDomain').value='';$('#goalHorizon').value='';$('#goalConfidence').value='high';$('#goalMetric').value='';$('#goalProgress').value='0';$('#experimentCategory').value='';$('#experimentDuration').value='14';$('#experimentSuccess').value='';$('#experimentProtocol').value='';$('#scheduleTime').value='09:00';$('#scheduleDuration').value='60';$('#scheduleCategory').value='';$('#memoryKind').value='seed';$('#memoryResonance').value='3';$('#memorySource').value='';$('#metricType').value='number';$('#metricUnit').value='';$('#metricTarget').value='';$('#metricFrequency').value='Daily';$('#metricDirection').value='up';$('#metricValue').value='';$$('#scheduleDayPicker input').forEach(x=>x.checked=false)}
function openCapture(type='Inbox',preset={}){resetCaptureExtras();$('#captureType').value=type;$('#captureEditId').value=preset.id||'';$('#captureTitle').value=preset.title||'';$('#captureNotes').value=preset.notes??preset.desc??preset.hypothesis??'';$('#captureDate').value=preset.date||'';$('#captureTime').value=preset.time||'';if(type==='Goal'){ $('#goalKind').value=preset.kind||'target';$('#goalDomain').value=preset.domain||'';$('#goalHorizon').value=preset.horizon||'';$('#goalConfidence').value=preset.confidence||'high';$('#goalMetric').value=preset.metric||'';$('#goalProgress').value=Number(preset.progress||0)}if(type==='Experiment'){ $('#experimentCategory').value=preset.category||'';$('#experimentDuration').value=Number(preset.duration||14);$('#experimentSuccess').value=preset.success||'';$('#experimentProtocol').value=preset.protocol||''}if(type==='Schedule'){ $('#scheduleTime').value=preset.time||'09:00';$('#scheduleDuration').value=Number(preset.duration||60);$('#scheduleCategory').value=preset.category||'';$$('#scheduleDayPicker input').forEach(x=>x.checked=(preset.days||[]).includes(Number(x.value)))}if(type==='Memory'){ $('#memoryKind').value=preset.kind||'seed';$('#memoryResonance').value=String(preset.resonance||3);$('#memorySource').value=preset.source||'';$('#captureNotes').value=preset.text||preset.notes||''}if(type==='Metric'){ $('#metricType').value=preset.type||'number';$('#metricUnit').value=preset.unit||'';$('#metricTarget').value=preset.target||'';$('#metricFrequency').value=preset.frequency||'Daily';$('#metricDirection').value=preset.direction||'up';$('#metricValue').value=preset.value||'';$('#captureNotes').value=preset.note||''}updateCaptureFields();modal.classList.add('open');modalBackdrop.classList.add('open');setTimeout(()=>$('#captureTitle').focus(),60)}
function closeCapture(){modal.classList.remove('open');modalBackdrop.classList.remove('open')}
$('#captureBtn').onclick=()=>openCapture();$$('[data-open-capture]').forEach(b=>b.onclick=()=>openCapture(b.dataset.captureType||'Inbox'));document.addEventListener('click',e=>{const b=e.target.closest('[data-open-capture]');if(b&&!b.onclick){e.preventDefault();openCapture(b.dataset.captureType||'Inbox')}});$('#captureType').onchange=()=>{$('#captureEditId').value='';updateCaptureFields()};$('#closeModal').onclick=$('#cancelCapture').onclick=closeCapture;modalBackdrop.onclick=()=>{closeCapture();closeCheckin()};
$('#saveCapture').onclick=()=>{const title=$('#captureTitle').value.trim(),type=$('#captureType').value,id=$('#captureEditId').value;if(!title){showToast('Add a title first');return}if(type==='Inbox'){inbox.push({title,meta:'Captured just now',type:'Inbox'});store.set('bp-inbox-v2',inbox);renderInbox()}else if(type==='Time block'){const date=$('#captureDate').value,time=$('#captureTime').value;if(!date||!time){showToast('Choose a date and time');return}customEvents.push({title,date,time});store.set('bp-events-v2',customEvents);renderCalendar()}else if(type==='Goal'){const item={id:id||'goal-'+Date.now(),kind:$('#goalKind').value,domain:$('#goalDomain').value.trim()||'Personal',horizon:$('#goalHorizon').value.trim()||'Custom · Direction',title,desc:$('#captureNotes').value.trim()||'Define why this matters and what evidence will show progress.',progress:Math.max(0,Math.min(100,Number($('#goalProgress').value)||0)),metric:$('#goalMetric').value.trim()||'Define evidence of progress',confidence:$('#goalConfidence').value,links:(goals.find(g=>g.id===id)?.links||[])};const i=goals.findIndex(g=>g.id===item.id);if(i>=0)goals[i]=item;else goals.push(item);store.set('bp-goals-v5',goals);renderGoals()}else if(type==='Experiment'){const old=experiments.find(x=>x.id===id);const item={id:id||'experiment-'+Date.now(),title,category:$('#experimentCategory').value.trim()||'Personal',hypothesis:$('#captureNotes').value.trim()||'What do you expect to change, and why?',duration:Math.max(1,Number($('#experimentDuration').value)||14),success:$('#experimentSuccess').value.trim()||'Define the evidence that would make this experiment useful.',protocol:$('#experimentProtocol').value.trim()||'Define one or two repeatable rules.',startedAt:old?.startedAt||ymd(new Date()),status:old?.status||'active'};const i=experiments.findIndex(x=>x.id===item.id);if(i>=0)experiments[i]=item;else experiments.push(item);store.set('bp-experiments-v5',experiments);renderExperiments();renderCheckins()}else if(type==='Schedule'){const days=$$('#scheduleDayPicker input:checked').map(x=>Number(x.value));const time=$('#scheduleTime').value;if(!days.length||!time){showToast('Choose at least one day and a time');return}const item={id:id||'schedule-'+Date.now(),title,notes:$('#captureNotes').value.trim(),days,time,duration:Math.max(5,Number($('#scheduleDuration').value)||60),category:$('#scheduleCategory').value.trim()||'Personal'};const i=schedules.findIndex(x=>x.id===item.id);if(i>=0)schedules[i]=item;else schedules.push(item);store.set('bp-schedules-v5',schedules);renderSchedules();renderCalendar()}else if(type==='Metric'){const item={id:id||'metric-'+Date.now(),title,type:$('#metricType').value,unit:$('#metricUnit').value.trim(),target:$('#metricTarget').value.trim()||'No target',frequency:$('#metricFrequency').value,direction:$('#metricDirection').value,value:$('#metricValue').value.trim()||'—',note:$('#captureNotes').value.trim()};const i=customMetrics.findIndex(m=>m.id===item.id);if(i>=0)customMetrics[i]=item;else customMetrics.push(item);store.set('bp-custom-metrics-v12',customMetrics);renderMetrics()}else if(type==='Memory'){const old=memories.find(m=>m.id===id);const item={id:id||'memory-'+Date.now(),title,text:$('#captureNotes').value.trim()||'A memory worth returning to.',kind:$('#memoryKind').value,resonance:Math.max(1,Math.min(5,Number($('#memoryResonance').value)||3)),source:$('#memorySource').value.trim()||'Personal observation',createdAt:old?.createdAt||ymd(new Date())};const i=memories.findIndex(m=>m.id===item.id);if(i>=0)memories[i]=item;else memories.unshift(item);store.set('bp-memories-v8',memories);renderMemory()}else{inbox.push({title,meta:`New ${type.toLowerCase()} · needs blueprint`,type});store.set('bp-inbox-v2',inbox);renderInbox()}closeCapture();showToast(`${type} ${id?'updated':'saved'}`);renderWorkspace();renderV12Hubs()};

function renderMetrics(){const grid=$('#customMetricGrid');if(!grid)return;const typeLabel={number:'Number',duration:'Duration',scale:'Scale',boolean:'Yes / No',currency:'Currency',count:'Count'};const arrow={up:'↑',down:'↓',neutral:'↔'};grid.innerHTML=customMetrics.length?customMetrics.map(m=>`<article class="custom-metric-card"><header><div><span class="metric-type">${typeLabel[m.type]||m.type} · ${escapeHTML(m.frequency||'Whenever logged')}</span><h3>${escapeHTML(m.title)}</h3></div><span class="pill">${arrow[m.direction]||'↔'}</span></header><p>${escapeHTML(m.note||'A signal you chose to make visible.')}</p><div class="metric-reading"><strong>${escapeHTML(m.value||'—')}${m.unit?` <small style="font-size:10px;color:var(--faint)">${escapeHTML(m.unit)}</small>`:''}</strong><span>Target<br>${escapeHTML(m.target||'No target')}</span></div><div class="metric-actions"><button data-edit-metric="${m.id}">Edit</button><button data-delete-metric="${m.id}">Remove</button></div></article>`).join(''):`<div class="empty-personal"><strong>No metrics yet.</strong><p>Add only signals that could actually change a decision.</p><button class="solid-btn" data-capture-type="Metric" data-open-capture>＋ Create metric</button></div>`;$('#labMetricCount')&&($('#labMetricCount').textContent=customMetrics.length)}
renderMetrics();
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-metric]');if(edit){const m=customMetrics.find(x=>x.id===edit.dataset.editMetric);if(m)openCapture('Metric',m)}const del=e.target.closest('[data-delete-metric]');if(del){customMetrics=customMetrics.filter(x=>x.id!==del.dataset.deleteMetric);store.set('bp-custom-metrics-v12',customMetrics);renderMetrics();showToast('Metric removed')}});

function journeyState(goalId){return goalJourneys[goalId]||{reviewCadence:'Monthly',nextReview:'',milestones:[],evidence:[],links:{metrics:[],experiments:[],schedules:[]}}}
function goalShapeCopy(kind){return {target:{label:'Target',accent:'var(--blue)',question:'What result would make this goal undeniably more true?',proof:'Use outcome progress, milestones, and the evidence that makes the result more likely.'},character:{label:'Character',accent:'var(--amber)',question:'What behavior would count as evidence that you practiced this trait?',proof:'Collect concrete behavioral evidence. Avoid turning identity into a score.'},system:{label:'System',accent:'var(--mint)',question:'Is this becoming easier to repeat without requiring more willpower?',proof:'Track repeatability, supporting rhythms, friction, and whether the intended result becomes easier.'},direction:{label:'Direction',accent:'var(--iris)',question:'Are recent choices moving in this direction often enough to keep it alive?',proof:'Use periodic reviews and evidence of aligned choices instead of a false completion percentage.'}}[kind]||{label:'Goal',accent:'var(--sage)',question:'What would count as useful evidence?',proof:'Keep the evidence specific enough to change a future decision.'}}
function v15DateLabel(v){if(!v)return'Not scheduled';const d=new Date(v+'T12:00:00');return isNaN(d)?v:d.toLocaleDateString('en-US',{month:'short',day:'numeric'})}
function v15ReviewDue(j){if(!j.nextReview)return false;const d=new Date(j.nextReview+'T23:59:59');return !isNaN(d)&&d<new Date()}
function goalJourneySignal(g,j){const s=goalShapeCopy(g.kind);if(g.kind==='target')return {label:'Outcome progress',value:`${g.progress}% · ${g.metric}`,pct:g.progress};if(g.kind==='character')return {label:'Behavioral evidence',value:`${j.evidence.length} observation${j.evidence.length===1?'':'s'} · ${j.reviewCadence||'Monthly'} review`,pct:Math.min(100,j.evidence.length*14)};if(g.kind==='system')return {label:'Repeatability evidence',value:`${(j.links?.schedules||[]).length} linked rhythm${(j.links?.schedules||[]).length===1?'':'s'} · ${j.evidence.length} notes`,pct:Math.min(100,20+(j.links?.schedules||[]).length*25+j.evidence.length*8)};return {label:'Direction check',value:`${j.evidence.length} evidence notes · next ${v15DateLabel(j.nextReview)}`,pct:Math.min(100,15+j.evidence.length*12)} }
function renderGoalJourneyOverview(){const el=$('#goalJourneyOverview');if(!el)return;const vals=goals.map(g=>journeyState(g.id));const withEvidence=vals.filter(j=>j.evidence?.length).length,due=vals.filter(v15ReviewDue).length,linked=vals.filter(j=>(j.links?.metrics?.length||0)+(j.links?.experiments?.length||0)+(j.links?.schedules?.length||0)>0).length;const msg=!goals.length?'Create one direction worth observing.':withEvidence===0?'Your goals exist; their evidence layer is still blank. Open one goal and record what would count as proof.':due?`${due} goal review${due===1?' is':'s are'} due. Use the review to change the architecture—not merely the percentage.`:`${withEvidence} of ${goals.length} goals have direct evidence attached. Keep the system specific enough to learn from.`;el.innerHTML=`<div class="journey-story"><span>Goal portfolio · v15</span><strong>Make each goal prove itself differently.</strong><p>${escapeHTML(msg)}</p></div><div class="journey-stat"><span>Evidence</span><strong>${withEvidence}/${goals.length||0}</strong><small>goals with observations</small></div><div class="journey-stat"><span>Linked systems</span><strong>${linked}</strong><small>metrics, experiments, or rhythms</small></div><div class="journey-stat"><span>Reviews due</span><strong>${due}</strong><small>scheduled checkpoints</small></div>`}
function renderGoals(){const grid=$('#goalGrid');if(!grid)return;grid.innerHTML=goals.length?goals.map(g=>{const j=journeyState(g.id),shape=goalShapeCopy(g.kind),sig=goalJourneySignal(g,j),review=v15ReviewDue(j)?'Review due':j.nextReview?`Review ${v15DateLabel(j.nextReview)}`:`${j.reviewCadence||'Monthly'} review`;const visual=g.kind==='target'?`<div class="progress"><i style="width:${Math.max(0,Math.min(100,g.progress))}%"></i></div>`:`<div class="shape-rail" style="--journey-accent:${shape.accent}"><i><b style="width:${sig.pct}%"></b></i><i><b style="width:${Math.max(0,sig.pct-25)}%"></b></i><i><b style="width:${Math.max(0,sig.pct-55)}%"></b></i></div>`;return `<article class="card goal-card customized" data-kind="${g.kind||'target'}" data-goal-open="${g.id}" style="--journey-accent:${shape.accent}"><div class="goal-top"><div><span class="goal-kind">${shape.label}</span><span class="goal-kind">${escapeHTML(g.domain||'Personal')}</span></div><span class="confidence ${g.confidence}">${g.confidence==='high'?'on track':'watch'}</span></div><span class="goal-horizon" style="display:inline-block;margin-top:12px">${escapeHTML(g.horizon)}</span><h3>${escapeHTML(g.title)}</h3><p>${escapeHTML(g.desc)}</p><div class="goal-metric"><strong>${g.kind==='target'?g.progress+'%':j.evidence.length}</strong><span>${escapeHTML(sig.label)}</span></div>${visual}<div class="journey-card-foot"><div><span>${escapeHTML(sig.label)}</span><strong>${escapeHTML(sig.value)}</strong></div><button class="journey-open" data-goal-open-button="${g.id}">${escapeHTML(review)} →</button></div><div class="entity-actions"><button data-edit-goal="${g.id}">Edit</button><button class="danger" data-delete-goal="${g.id}">Delete</button></div></article>`}).join(''):`<div class="empty-personal"><strong>No active goals yet.</strong><p>Create a target, character practice, system, or direction. Blueprint should adapt to the goal—not force the goal into one format.</p><button class="solid-btn" data-capture-type="Goal" data-open-capture>＋ Create goal</button></div>`;$('#goalCount').textContent=goals.length;$('#goalNavCount')&&($('#goalNavCount').textContent=goals.length);$('#settingsGoalCount')&&($('#settingsGoalCount').textContent=goals.length);$('#planGoalCount')&&($('#planGoalCount').textContent=goals.length);const map=$('#systemMap');if(map)map.innerHTML=goals.length?goals.slice(0,3).map((g,i)=>{const j=journeyState(g.id),shape=goalShapeCopy(g.kind);return `<div class="card system-map-card" data-goal-open="${g.id}" style="cursor:pointer;--journey-accent:${shape.accent}"><span>${escapeHTML(g.domain||['Direction','Capacity','Horizon'][i]||'Goal')}</span><strong>${escapeHTML(g.title)}</strong><p>${escapeHTML(g.desc)}</p><div class="connection-chip">◎ ${j.evidence.length} evidence · ${(j.links?.metrics||[]).length+(j.links?.experiments||[]).length+(j.links?.schedules||[]).length} links</div></div>`}).join(''):'<div class="empty-personal"><strong>Your system map starts with a goal.</strong><p>Create a direction worth scheduling around.</p></div>';renderGoalJourneyOverview()}
renderGoals();
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-goal]');if(edit){const g=goals.find(x=>x.id===edit.dataset.editGoal);if(g)openCapture('Goal',g)}const del=e.target.closest('[data-delete-goal]');if(del){const id=del.dataset.deleteGoal;goals=goals.filter(x=>x.id!==id);store.set('bp-goals-v5',goals);renderGoals();renderWorkspace();showToast('Goal deleted')}});


function experimentDay(exp){const start=new Date(`${exp.startedAt}T12:00:00`),now=new Date();return Math.max(1,Math.min(exp.duration,Math.floor((now-start)/86400000)+1))}
function experimentStats(id){const logs=checkins.filter(x=>x.experiment===id);const avg=logs.length?(logs.reduce((a,x)=>a+x.focus,0)/logs.length).toFixed(1):'—';const adherent=logs.length?Math.round(logs.filter(x=>x.adherence==='yes').length/logs.length*100):0;return {logs:logs.length,avg,adherent}}
function renderExperiments(){const grid=$('#experimentGrid');if(!grid)return;grid.innerHTML=experiments.length?experiments.map(x=>{const st=experimentStats(x.id),day=experimentDay(x),pct=Math.round(day/x.duration*100);return `<div class="card experiment-card" data-detail="${x.id}"><div class="top"><div><span class="tag">${escapeHTML(x.category)}</span><span class="entity-badge">personalizable</span></div><span>Day ${day} / ${x.duration}</span></div><h3>${escapeHTML(x.title)}</h3><p>${escapeHTML(x.hypothesis)}</p><div class="metric-row"><div class="metric"><span>Adherence</span><strong>${st.logs?st.adherent+'%':'—'}</strong></div><div class="metric"><span>Avg focus</span><strong>${st.avg}</strong></div><div class="metric"><span>Logs</span><strong>${st.logs}</strong></div></div><div class="experiment-actions"><button class="soft-btn" data-checkin="${x.id}">Log check-in</button><span class="log-count" id="checkin-count-${x.id}">${st.logs} logs</span></div></div>`}).join(''):`<div class="empty-personal"><strong>Your lab is empty.</strong><p>Create a bounded experiment with a hypothesis, duration, protocol, and success criterion.</p><button class="solid-btn" data-capture-type="Experiment" data-open-capture="">＋ Create experiment</button></div>`;renderLabPulse();$('#experimentNavCount')&&($('#experimentNavCount').textContent=experiments.length);$('#settingsExperimentCount')&&($('#settingsExperimentCount').textContent=experiments.length)}
function renderLabPulse(){const wrap=$('#labPulse');if(!wrap)return;const active=experiments.filter(x=>x.status!=='archived').slice(0,3);$('#labPulseCount').textContent=`${active.length} running`;wrap.innerHTML=active.length?active.map(x=>{const st=experimentStats(x.id),day=experimentDay(x),pct=Math.round(day/x.duration*100);return `<div class="lab-item" data-detail="${x.id}"><div class="lab-top"><span class="tag">${escapeHTML(x.category)}</span><strong>${escapeHTML(x.title)}</strong><span class="day">${day} / ${x.duration}</span></div><div class="progress"><i style="width:${pct}%"></i></div><footer><span>${st.logs?`Adherence ${st.adherent}%`:'No logs yet'}</span><span>${st.logs?`Focus ${st.avg}`:'Start observing'}</span></footer></div>`}).join(''):'<div class="card-pad"><p class="subhead">No active experiments. Create one when you have a specific question worth testing.</p></div>'}
function renderSchedules(){const days=['M','T','W','T','F','S','S'];const html=schedules.length?schedules.map(x=>`<article class="card schedule-card"><div class="schedule-card-head"><div><span class="schedule-kind">${escapeHTML(x.category)} · recurring</span><h3>${escapeHTML(x.title)}</h3></div><span class="confidence high">${escapeHTML(x.time)}</span></div><p>${escapeHTML(x.notes||'A recurring block in your personal architecture.')}</p><div class="schedule-days">${days.map((d,i)=>`<i class="${x.days.includes(i)?'on':''}">${d}</i>`).join('')}</div><div class="schedule-meta"><span>${x.duration} min · ${x.days.length}× / week</span><div class="entity-actions" style="margin:0"><button data-edit-schedule="${x.id}">Edit</button><button class="danger" data-delete-schedule="${x.id}">Delete</button></div></div></article>`).join(''):`<div class="empty-personal"><strong>No recurring blocks yet.</strong><p>Add the rhythms that make your week feel like yours—training, writing, study, family time, recovery, or anything else.</p><button class="solid-btn" data-capture-type="Schedule" data-open-capture="">＋ Add schedule</button></div>`;['scheduleList','calendarScheduleList'].forEach(id=>{const el=$('#'+id);if(el)el.innerHTML=html});$('#settingsScheduleCount')&&($('#settingsScheduleCount').textContent=schedules.length)}
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-schedule]');if(edit){e.stopPropagation();const item=schedules.find(x=>x.id===edit.dataset.editSchedule);if(item)openCapture('Schedule',item)}const del=e.target.closest('[data-delete-schedule]');if(del){e.stopPropagation();schedules=schedules.filter(x=>x.id!==del.dataset.deleteSchedule);store.set('bp-schedules-v5',schedules);renderSchedules();renderCalendar();renderWorkspace();showToast('Schedule deleted')}});
function initials(name){const n=(name||'Blueprint').trim().split(/\s+/).filter(Boolean);return (n.slice(0,2).map(x=>x[0]).join('')||'BP').toUpperCase()}
function renderWorkspace(){const name=profile.name?.trim()||'Your workspace',role=profile.role?.trim()||'Private · local workspace';$('#profileAvatar').textContent=initials(profile.name);$('#profileSidebarName').textContent=name;$('#profileSidebarRole').textContent=role;$('#northStarDisplay').textContent=profile.northStar||defaultProfile.northStar;$('#primaryOutcome').textContent=profile.focus||defaultProfile.focus;$('#heroCopy').textContent=profile.note||defaultProfile.note;$('#settingsAvatarPreview').textContent=initials(profile.name);$('#settingsNamePreview').textContent=name;$('#settingsRolePreview').textContent=role;$('#settingsNorthStarPreview').textContent=profile.northStar||defaultProfile.northStar;$('#settingsFocusPreview').textContent=profile.focus||defaultProfile.focus;$('#settingsGoalCount').textContent=goals.length;$('#settingsExperimentCount').textContent=experiments.length;$('#settingsScheduleCount').textContent=schedules.length;$('#goalOverviewExperimentCount')&&($('#goalOverviewExperimentCount').textContent=experiments.length);$('#goalOverviewScheduleCount')&&($('#goalOverviewScheduleCount').textContent=schedules.length);setDateUI()}

