/* v19 · Data Vault */
const VAULT_META_KEY='bp-vault-meta-v19';
let pendingVaultImport=null;
function accountStorageSnapshot(){
  if(!activeAccount)return{};
  const prefix=`bp-user:${activeAccount.id}:`,data={};
  for(let i=0;i<rawStorage.length;i++){
    const key=rawStorage.key(i);if(!key||!key.startsWith(prefix))continue;
    const suffix=key.slice(prefix.length);if(suffix.startsWith('bp-vault-'))continue;
    const value=rawStorage.getItem(key);if(value!=null)data[suffix]=value;
  }
  return data;
}
function approxBytes(obj){try{return new TextEncoder().encode(JSON.stringify(obj)).length}catch{return JSON.stringify(obj).length}}
function formatBytes(bytes){if(bytes<1024)return`${bytes} B`;if(bytes<1048576)return`${(bytes/1024).toFixed(bytes<10240?1:0)} KB`;return`${(bytes/1048576).toFixed(1)} MB`}
function relativeAge(iso){if(!iso)return'—';const ms=Math.max(0,Date.now()-new Date(iso).getTime()),m=Math.floor(ms/60000);if(m<1)return'Now';if(m<60)return`${m}m`;const h=Math.floor(m/60);if(h<48)return`${h}h`;const d=Math.floor(h/24);return`${d}d`}
async function sha256Text(text){try{if(!globalThis.crypto?.subtle)return null;const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return bytesToBase64(new Uint8Array(hash))}catch{return null}}
async function buildBackupPayload(){const data=accountStorageSnapshot(),payload={format:'blueprint-workspace',version:19,exportedAt:new Date().toISOString(),source:{accountKind:activeAccount?.guest?'guest':'account',profileName:profile?.name||activeAccount?.name||'Blueprint user'},data};payload.integrity=await sha256Text(JSON.stringify(data));return payload}
function downloadVaultFile(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backupFilename(suffix='json'){const who=(profile?.name||activeAccount?.name||'blueprint').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'blueprint',day=new Date().toISOString().slice(0,10);return`${who}-blueprint-${day}.${suffix}`}
async function deriveVaultKey(passphrase,salt,uses=['encrypt']){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(passphrase),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,uses)}
async function encryptVaultPayload(payload,passphrase){if(!globalThis.crypto?.subtle)throw new Error('Encrypted backups require Web Crypto in this browser.');const salt=new Uint8Array(16),iv=new Uint8Array(12);crypto.getRandomValues(salt);crypto.getRandomValues(iv);const key=await deriveVaultKey(passphrase,salt,['encrypt']);const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(payload)));return{format:'blueprint-encrypted-backup',version:19,cipher:'AES-GCM',kdf:'PBKDF2-SHA256',iterations:180000,salt:bytesToBase64(salt),iv:bytesToBase64(iv),ciphertext:bytesToBase64(new Uint8Array(cipher))}}
async function decryptVaultPayload(wrapper,passphrase){if(!globalThis.crypto?.subtle)throw new Error('This browser cannot decrypt the backup.');const key=await deriveVaultKey(passphrase,base64ToBytes(wrapper.salt),['decrypt']);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:base64ToBytes(wrapper.iv)},key,base64ToBytes(wrapper.ciphertext));return JSON.parse(new TextDecoder().decode(plain))}
function validateVaultPayload(payload){if(!payload||payload.format!=='blueprint-workspace'||payload.version<18||!payload.data||typeof payload.data!=='object'||Array.isArray(payload.data))throw new Error('This is not a valid Blueprint workspace backup.');const entries=Object.entries(payload.data);if(entries.length>300)throw new Error('Backup contains too many datasets.');for(const [k,v] of entries){if(typeof k!=='string'||k.length>160||typeof v!=='string')throw new Error('Backup contains an invalid dataset.')}return payload}
function clearActiveWorkspace(){if(!activeAccount)return;const prefix=`bp-user:${activeAccount.id}:`,keys=[];for(let i=0;i<rawStorage.length;i++){const k=rawStorage.key(i);if(k?.startsWith(prefix)&&!k.slice(prefix.length).startsWith('bp-vault-'))keys.push(k)}keys.forEach(k=>rawStorage.removeItem(k))}
function restoreVaultPayload(payload,mode='merge'){validateVaultPayload(payload);if(mode==='replace')clearActiveWorkspace();const prefix=`bp-user:${activeAccount.id}:`;Object.entries(payload.data).forEach(([suffix,value])=>rawStorage.setItem(prefix+suffix,value));const meta=store.get(VAULT_META_KEY,{});store.set(VAULT_META_KEY,{...meta,lastRestoreAt:new Date().toISOString(),lastRestoreMode:mode});}
function setSessionPolicy(policy){if(!activeAccount||activeAccount.guest)return;const all=rawGet(AUTH_POLICY_KEY,{})||{};all[activeAccount.id]=policy;rawSet(AUTH_POLICY_KEY,all)}
function renderVault(){
  const card=$('#dataVaultCard');if(!card||!activeAccount)return;
  const snap=accountStorageSnapshot(),meta=store.get(VAULT_META_KEY,{}),session=authSession();
  $('#vaultDatasetCount').textContent=Object.keys(snap).length;
  $('#vaultSize').textContent=formatBytes(approxBytes(snap));
  $('#vaultSessionAge').textContent=activeAccount.guest?'Guest':relativeAge(session?.at);
  $('#vaultSessionMeta').textContent=activeAccount.guest?'temporary local workspace':'since sign-in';
  $('#vaultLastBackup').textContent=meta.lastBackupAt?relativeAge(meta.lastBackupAt):'Never';
  $('#vaultBackupMeta').textContent=meta.lastBackupAt?new Date(meta.lastBackupAt).toLocaleString():'Create one before major changes';
  $('#vaultStateLabel').textContent=activeAccount.guest?'Guest · local only':'Account isolated · local-first';
  $('#vaultSecurityBadge').textContent=activeAccount.guest?'Guest':'Account';
  $('#vaultNamespace').textContent=activeAccount.guest?'guest workspace':`…${String(activeAccount.id).slice(-10)}`;
  $('#vaultCryptoState').textContent=globalThis.crypto?.subtle?'PBKDF2 + AES-GCM':'Fallback only';
  $('#vaultCredentialText').textContent=activeAccount.guest?'Guest mode has no password. Upgrade it to an account to add credentials.':(globalThis.crypto?.subtle?'Password verification uses a salted PBKDF2 digest. Encrypted exports use a separate passphrase and AES-GCM.':'This environment lacks Web Crypto; local credential fallback is less suitable for production.');
  const policy=$('#vaultSessionPolicy');if(policy){policy.value=activeAccount.guest?'never':sessionPolicyFor(activeAccount.id);policy.disabled=!!activeAccount.guest}
  $('#vaultPasswordForm').style.display=activeAccount.guest?'none':'grid';
  $('#vaultExportEncrypted').disabled=!globalThis.crypto?.subtle;
}
$('#vaultExportJson')?.addEventListener('click',async()=>{if(!activeAccount)return;const payload=await buildBackupPayload();downloadVaultFile(backupFilename('json'),JSON.stringify(payload,null,2));store.set(VAULT_META_KEY,{...store.get(VAULT_META_KEY,{}),lastBackupAt:new Date().toISOString(),lastBackupType:'json'});renderVault();showToast('Readable backup exported')});
$('#vaultExportEncrypted')?.addEventListener('click',async()=>{const pass=$('#vaultExportPassphrase').value;if(pass.length<8){showToast('Use an 8+ character backup passphrase');return}try{const payload=await buildBackupPayload(),wrapped=await encryptVaultPayload(payload,pass);downloadVaultFile(backupFilename('blueprint'),JSON.stringify(wrapped));$('#vaultExportPassphrase').value='';store.set(VAULT_META_KEY,{...store.get(VAULT_META_KEY,{}),lastBackupAt:new Date().toISOString(),lastBackupType:'encrypted'});renderVault();showToast('Encrypted backup exported')}catch(err){showToast(err.message||'Could not export backup')}});
$('#vaultChooseBackup')?.addEventListener('click',()=>$('#vaultImportFile')?.click());
$('#vaultImportFile')?.addEventListener('change',async e=>{const file=e.target.files?.[0];pendingVaultImport=null;const state=$('#vaultFileState'),btn=$('#vaultRestoreBtn');btn.disabled=true;if(!file){state.innerHTML='<strong>No backup selected</strong><span>Blueprint backup files are validated before anything is changed.</span>';return}try{const parsed=JSON.parse(await file.text());if(!['blueprint-workspace','blueprint-encrypted-backup'].includes(parsed?.format))throw new Error('Unrecognized Blueprint backup format.');pendingVaultImport={file,parsed};state.innerHTML=`<strong>${escapeAttrLocal(file.name)}</strong><span>${parsed.format==='blueprint-encrypted-backup'?'Encrypted backup · passphrase required':'Readable backup'} · ${formatBytes(file.size)}</span>`;btn.disabled=false;$('#vaultImportPassphrase').style.display=parsed.format==='blueprint-encrypted-backup'?'block':'none'}catch(err){state.innerHTML=`<strong>Could not read this file</strong><span>${escapeAttrLocal(err.message||'Invalid JSON backup')}</span>`}});
$('#vaultRestoreBtn')?.addEventListener('click',async()=>{if(!pendingVaultImport)return;try{let payload=pendingVaultImport.parsed;if(payload.format==='blueprint-encrypted-backup'){const pass=$('#vaultImportPassphrase').value;if(!pass)throw new Error('Enter the backup passphrase first.');payload=await decryptVaultPayload(payload,pass)}validateVaultPayload(payload);const mode=$('#vaultImportMode').value;if(!confirm(`${mode==='replace'?'Replace this workspace':'Merge this backup'} with ${Object.keys(payload.data).length} datasets?`))return;restoreVaultPayload(payload,mode);showToast('Backup restored');setTimeout(()=>location.reload(),350)}catch(err){showToast(err.name==='OperationError'?'Passphrase is incorrect or the file is damaged.':(err.message||'Could not restore backup'))}});

// v20 · local-first sync foundation
const defaultSyncMeta={conflictPolicy:'ask',posture:'gentle',lastCheckpointAt:'',lastJournalClearAt:'',schemaVersion:20};
function syncMeta(){return {...defaultSyncMeta,...rawScopedGet(SYNC_META_KEY,{})}}
function setSyncMeta(patch){rawScopedSet(SYNC_META_KEY,{...syncMeta(),...patch})}
function syncJournal(){return rawScopedGet(SYNC_JOURNAL_KEY,[])}
function syncCheckpoints(){return rawScopedGet(SYNC_CHECKPOINTS_KEY,[])}
function syncWorkspaceSnapshot(){const snap=accountStorageSnapshot(),clean={};Object.entries(snap).forEach(([k,v])=>{if(!k.startsWith('bp-sync-'))clean[k]=v});return clean}
function formatSyncAgo(iso){if(!iso)return'Never';const ms=Date.now()-new Date(iso).getTime(),m=Math.max(0,Math.floor(ms/60000));if(m<1)return'Just now';if(m<60)return`${m}m ago`;const h=Math.floor(m/60);if(h<24)return`${h}h ago`;return`${Math.floor(h/24)}d ago`}
function syncDatasetLabel(key){return key.replace(/^bp-/,'').replace(/-v\d+$/,'').replaceAll('-',' ').replace(/\b\w/g,c=>c.toUpperCase())}
async function createSyncCheckpoint(label='Restore point'){if(!activeAccount)return;const data=syncWorkspaceSnapshot(),cp={id:`checkpoint-${Date.now()}`,label,at:new Date().toISOString(),deviceId:syncDevice.id,data,integrity:await sha256Text(JSON.stringify(data))};const all=syncCheckpoints();all.unshift(cp);rawScopedSet(SYNC_CHECKPOINTS_KEY,all.slice(0,5));rawScopedSet(SYNC_JOURNAL_KEY,[]);setSyncMeta({lastCheckpointAt:cp.at,lastJournalClearAt:cp.at});renderSyncCenter();showToast('Restore point created')}
function restoreSyncCheckpoint(id){const cp=syncCheckpoints().find(x=>x.id===id);if(!cp||!confirm(`Restore “${cp.label}”? Current workspace data will be replaced, while Sync Center history stays available.`))return;const prefix=`bp-user:${activeAccount.id}:`,keys=[];for(let i=0;i<rawStorage.length;i++){const k=rawStorage.key(i);if(k?.startsWith(prefix)){const suffix=k.slice(prefix.length);if(!suffix.startsWith('bp-sync-')&&!suffix.startsWith('bp-vault-'))keys.push(k)}}syncMutationMuted=true;try{keys.forEach(k=>rawStorage.removeItem(k));Object.entries(cp.data).forEach(([suffix,value])=>rawStorage.setItem(prefix+suffix,value));rawScopedSet(SYNC_JOURNAL_KEY,[]);setSyncMeta({lastCheckpointAt:cp.at,lastJournalClearAt:new Date().toISOString()})}finally{syncMutationMuted=false}showToast('Restore point recovered');setTimeout(()=>location.reload(),260)}
function deleteSyncCheckpoint(id){rawScopedSet(SYNC_CHECKPOINTS_KEY,syncCheckpoints().filter(x=>x.id!==id));renderSyncCenter();showToast('Restore point removed')}
function renderSyncCenter(){const root=$('#page-sync');if(!root||!activeAccount)return;const journal=syncJournal(),points=syncCheckpoints(),meta=syncMeta(),last=points[0]?.at||meta.lastCheckpointAt;$('#syncPendingCount').textContent=journal.length;$('#syncCheckpointCount').textContent=points.length;$('#syncDeviceShort').textContent=syncDevice.name||'This device';$('#syncLastCheckpoint').textContent=last?formatSyncAgo(last):'Never';$('#syncHeroMeta').textContent=`${journal.length} pending ${journal.length===1?'change':'changes'}`;$('#syncHeroState').textContent=activeAccount.guest?'Guest · local':'Local-first';$('#syncDeviceLabel').textContent=syncDevice.name||'This device';$('#syncDeviceName').value=syncDevice.name||'This device';$('#syncDeviceMeta').textContent=`${String(syncDevice.id).slice(-12)} · created ${new Date(syncDevice.createdAt).toLocaleDateString()}`;$('#syncConflictPolicy').value=meta.conflictPolicy||'ask';$('#syncPosture').value=meta.posture||'gentle';const j=$('#syncJournalList');j.innerHTML=journal.length?journal.slice(0,14).map(e=>`<div class="sync-event"><i></i><div><strong>${escapeHTML(syncDatasetLabel(e.key))}</strong><small>${e.op==='remove'?'Removed':'Changed'} on ${escapeHTML(syncDevice.name||'this device')}</small></div><time>${formatSyncAgo(e.at)}</time></div>`).join(''):'<div class="sync-empty">No uncheckpointed changes. Your local state has a clean anchor.</div>';const c=$('#syncCheckpointList');c.innerHTML=points.length?points.map((p,i)=>`<div class="checkpoint"><div><strong>${escapeHTML(p.label||`Restore point ${i+1}`)}</strong><small>${new Date(p.at).toLocaleString()} · ${Object.keys(p.data||{}).length} datasets · ${String(p.integrity||'').slice(0,10)}</small></div><div class="checkpoint-actions"><button data-restore-sync="${p.id}">Restore</button><button data-delete-sync="${p.id}">×</button></div></div>`).join(''):'<div class="sync-empty">Create a restore point before a major restructure, import, or migration.</div>'}
$('#syncDeviceName')?.addEventListener('change',e=>{const name=e.target.value.trim()||'This device';const d={...syncDevice,name,lastSeenAt:new Date().toISOString()};Object.assign(syncDevice,d);rawSet(SYNC_DEVICE_KEY,d);renderSyncCenter();showToast('Device renamed')});
