$('#syncExportManifest')?.addEventListener('click',async()=>{const data=syncWorkspaceSnapshot(),meta=syncMeta(),manifest={format:'blueprint-cloud-migration',version:20,exportedAt:new Date().toISOString(),account:{kind:activeAccount?.guest?'guest':'local-account',name:profile?.name||activeAccount?.name||'Blueprint user'},device:{id:syncDevice.id,name:syncDevice.name},policy:{conflict:meta.conflictPolicy,posture:meta.posture},revisionJournal:syncJournal(),workspace:data,integrity:await sha256Text(JSON.stringify(data))};downloadVaultFile(`blueprint-cloud-migration-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(manifest,null,2));showToast('Migration bundle exported')});
