$('#vaultChangePassword')?.addEventListener('click',async()=>{if(!activeAccount||activeAccount.guest)return;const oldPass=$('#vaultOldPassword').value,newPass=$('#vaultNewPassword').value;if(newPass.length<8){showToast('New password must be at least 8 characters');return}const current=authAccounts().find(a=>a.id===activeAccount.id);if(!current)return;const oldHash=await passwordDigest(oldPass,current.salt);if(oldHash!==current.passwordHash){showToast('Current password does not match');return}const salt=makeSalt(),passwordHash=await passwordDigest(newPass,salt),accounts=authAccounts().map(a=>a.id===current.id?{...a,salt,passwordHash,passwordChangedAt:new Date().toISOString()}:a);rawSet(AUTH_ACCOUNTS_KEY,accounts);$('#vaultOldPassword').value='';$('#vaultNewPassword').value='';showToast('Local account password changed')});
