function renderRoutines(){Object.keys(routineLabels).forEach(id=>{const done=!!routineDone[routineKey(id)];$$(`[data-routine-card="${id}"]`).forEach(x=>x.classList.toggle('done',done));$$(`[data-routine-toggle="${id}"]`).forEach(x=>{if(x.classList.contains('routine-complete'))x.textContent=done?'Done ✓':'Mark done';const row=x.closest('.routine-mini-row');if(row)row.classList.toggle('done',done)});const status=$(`#today-routine-${id}`);if(status)status.textContent=done?'done':'due';});const ids=Object.keys(routineLabels),done=ids.filter(id=>routineDone[routineKey(id)]).length;const el=$('#routineAdherence');if(el)el.textContent=`${Math.round((done/ids.length)*100)}%`;}
