function renderReview(){const keys=['inbox','plan','lab','protect'],touched=keys.filter(k=>reviewState[k]).length;$('#reviewProgressText').textContent=touched?`${touched} lens${touched===1?'':'es'} touched`:'No lenses touched';$('#reviewProgressBar').style.width=`${touched/4*100}%`;$('[data-review-step]').forEach(b=>{const on=!!reviewState[b.dataset.reviewStep];b.classList.toggle('done',on);b.querySelector('em').textContent=on?'✓':'○'});
const cutoff=Date.now()-7*86400000,recentCheckins=(checkins||[]).filter(x=>{const t=new Date(x.date||x.createdAt||0).getTime();return Number.isFinite(t)&&t>=cutoff}).length,designs=store.get('bp-day-design-v27',{})||{},designCount=Object.entries(designs).filter(([date,v])=>{const raw=v?.updatedAt||date;const t=/^\d{4}-\d{2}-\d{2}$/.test(String(raw))?new Date(raw+'T12:00:00').getTime():new Date(raw).getTime();return Number.isFinite(t)&&t>=cutoff}).length,weeks=store.get('bp-week-plans-v17',{})||{},weekCount=Object.keys(weeks).length,loose=(inbox||[]).length,total=loose+recentCheckins+designCount+(weekCount?1:0);
const head=$('#learningReviewHeadline'),copy=$('#learningReviewCopy');if(head&&copy){if(!total){head.textContent='Nothing needs a review just because a week passed.';copy.textContent='Live first. When evidence, friction, or an unresolved choice appears, Blueprint will give you something real to think with.'}else{head.textContent=`${total} workspace signal${total===1?' is':'s are'} available to think with.`;copy.textContent='Use one useful signal or question. You do not need to process everything, finish every lens, or produce a verdict.'}}
const queue=$('#learningReviewQueue');if(queue){const items=[];if(loose)items.push(`<div class="card review-item" data-page-jump="inbox"><div class="review-icon">⌑</div><div><strong>Loose ends</strong><p>${loose} unresolved follow-up${loose===1?'':'s'} are available if any still matter.</p></div><time>Open</time></div>`);if(recentCheckins)items.push(`<div class="card review-item" data-page-jump="experiments"><div class="review-icon">⌁</div><div><strong>Experiment observations</strong><p>${recentCheckins} observation${recentCheckins===1?'':'s'} from the last seven days can be interpreted when useful.</p></div><time>Lab</time></div>`);if(designCount)items.push(`<div class="card review-item" data-page-jump="today"><div class="review-icon">◫</div><div><strong>Recent Day Designs</strong><p>${designCount} designed day${designCount===1?'':'s'} can help you notice where structure fit or needed adaptation.</p></div><time>Today</time></div>`);if(weekCount)items.push(`<div class="card review-item" data-page-jump="week"><div class="review-icon">◎</div><div><strong>Week Design</strong><p>Your saved week gives you a reference point for comparing intention with reality.</p></div><time>Plan</time></div>`);queue.innerHTML=items.length?items.join(''):'<div class="card archive-empty"><div><div class="glyph">↻</div><h3>No review queue to clear.</h3><p>That is a valid state. Reflect when something is worth understanding, not because the calendar demands it.</p></div></div>'}}
