function openDrawer(key){const exp=experiments.find(x=>x.id===key);if(exp){const st=experimentStats(exp.id),day=experimentDay(exp),protocol=String(exp.protocol||'').split(/\n+/).filter(Boolean);drawerBody.innerHTML=`<div class="eyebrow">Experiment · ${escapeHTML(exp.category)}</div><h2 class="drawer-title">${escapeHTML(exp.title)}</h2><p class="drawer-desc">${escapeHTML(exp.hypothesis)}</p><div class="mini-grid"><div class="mini"><span>Day</span><strong>${day} / ${exp.duration}</strong></div><div class="mini"><span>Adherence</span><strong>${st.logs?st.adherent+'%':'—'}</strong></div><div class="mini"><span>Avg focus</span><strong>${st.avg}</strong></div></div><div class="detail-section"><h4>Success criterion</h4><div class="detail-box"><p>${escapeHTML(exp.success)}</p></div></div><div class="detail-section"><h4>Protocol</h4><div class="detail-box">${protocol.length?protocol.map((m,i)=>`<div class="milestone"><i>${i+1}</i><div><strong>${escapeHTML(m)}</strong><small>Personal protocol</small></div></div>`).join(''):`<p>No protocol steps yet.</p>`}</div></div><div class="detail-section"><h4>Evidence log</h4><div class="detail-box"><p>${st.logs} check-ins recorded in this browser. Keep observations lightweight enough to sustain.</p></div></div><div class="drawer-actions"><button class="solid-btn" data-checkin="${exp.id}">Log check-in</button><button class="soft-btn" data-edit-experiment="${exp.id}">Edit experiment</button><button class="soft-btn" data-delete-experiment="${exp.id}">Delete</button></div>`;drawer.classList.add('open');drawerBackdrop.classList.add('open');return}const d=detailData[key];if(!d||d.type!=='Project')return;const path=d.type==='Project'&&projectPaths[key]?`<div class="detail-section"><h4>Critical path</h4><div class="critical-path">${projectPaths[key].map((m,i)=>`<div class="critical-node ${m[0]}"><i>${m[0]==='done'?'✓':i+1}</i><strong>${m[1]}</strong><em>${m[2]}</em></div>`).join('')}</div></div>`:'';const connections=detailConnections[key]?.length?`<div class="detail-section"><h4>Connected system</h4><div class="detail-connections">${detailConnections[key].map(x=>`<span class="detail-connection">${x}</span>`).join('')}</div></div>`:'';drawerBody.innerHTML=`<div class="eyebrow">${d.type} · ${d.tag}</div><h2 class="drawer-title">${d.title}</h2><p class="drawer-desc">${d.desc}</p><div class="mini-grid">${d.stats.map(x=>`<div class="mini"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div>${connections}<div class="detail-section"><h4>Why it matters</h4><div class="detail-box"><p>${d.why}</p></div></div><div class="detail-section"><h4>Next move</h4><div class="detail-box"><p>${d.next}</p></div></div>${path}<div class="detail-section"><h4>Milestones</h4><div class="detail-box">${d.milestones.map(m=>`<div class="milestone ${m[0]}"><i>${m[0]==='done'?'✓':''}</i><div><strong>${m[1]}</strong><small>${m[2]}</small></div></div>`).join('')}</div></div><div class="drawer-actions"><button class="solid-btn" data-toast="Progress logged">Log progress</button><button class="soft-btn" data-toast="Note added">Add note</button></div>`;drawer.classList.add('open');drawerBackdrop.classList.add('open')}
function closeDrawer(){drawer.classList.remove('open');drawerBackdrop.classList.remove('open')}
