let weekOffset=0;const baseMonday=new Date(2026,8,21);const builtinEvents={
'0-8':['Morning run','amber'],'0-9':['Deep work',''],'0-13':['Project Atlas',''],'0-18':['Gym','amber'],
'1-9':['Deep work',''],'1-11':['Research review','mint'],'1-15':['Admin reset',''],
'2-8':['Strength','amber'],'2-10':['Website sprint',''],'2-14':['Walk + notes','mint'],
'3-9':['Deep work',''],'3-13':['Atlas synthesis',''],'3-17':['Experiment log','mint'],
'4-8':['Run','amber'],'4-10':['Case study writing',''],'4-16':['Weekly review','mint'],
'5-10':['Long run','amber'],'6-13':['Plan next week','mint'],'0-17':['Shutdown ritual','mint'],'1-17':['Shutdown ritual','mint'],'2-17':['Shutdown ritual','mint'],'4-17':['Weekly review','mint']};
function mondayForOffset(){const d=new Date(baseMonday);d.setDate(d.getDate()+weekOffset*7);return d}
function ymd(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function renderCalendar(){const grid=$('#calendarGrid'),monday=mondayForOffset(),days=[];for(let i=0;i<7;i++){const d=new Date(monday);d.setDate(d.getDate()+i);days.push(d)}const end=days[6];$('#weekLabel').textContent=`${new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'}).format(monday)} – ${new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'}).format(end)}`;let html='<div class="cal-head"></div>'+days.map((d,i)=>`<div class="cal-head ${weekOffset===0&&i===0?'today':''}"><div><span>${new Intl.DateTimeFormat('en-US',{weekday:'short'}).format(d)}</span><strong>${d.getDate()}</strong></div></div>`).join('');const startHour=Math.max(0,Math.min(22,parseInt((profile.dayStart||'08:00').slice(0,2))||8)),endHour=Math.max(startHour+1,Math.min(23,parseInt((profile.dayEnd||'18:00').slice(0,2))||18));for(let hour=startHour;hour<=endHour;hour++){html+=`<div class="cal-time">${String(hour).padStart(2,'0')}:00</div>`;days.forEach((date,day)=>{const built=weekOffset===0?builtinEvents[`${day}-${hour}`]:null;const custom=customEvents.find(e=>e.date===ymd(date)&&Number(e.time.slice(0,2))===hour);const recurring=schedules.find(x=>x.days.includes(day)&&Number(x.time.slice(0,2))===hour);const ev=custom?[custom.title,'mint']:recurring?[recurring.title,'mint']:built;html+=`<div class="cal-cell" data-date="${ymd(date)}" data-hour="${String(hour).padStart(2,'0')}:00">${ev?`<div class="cal-event ${ev[1]||''}">${escapeHTML(ev[0])}</div>`:''}</div>`})}grid.innerHTML=html}
renderCalendar();$('#prevWeek').onclick=()=>{weekOffset--;renderCalendar()};$('#nextWeek').onclick=()=>{weekOffset++;renderCalendar()};$('#thisWeek').onclick=()=>{weekOffset=0;renderCalendar()};
$('#calendarGrid').onclick=e=>{const cell=e.target.closest('.cal-cell');if(cell&&!e.target.closest('.cal-event'))openCapture('Time block',{date:cell.dataset.date,time:cell.dataset.hour})};

