const command=$('#command'),commandBackdrop=$('#commandBackdrop'),commandInput=$('#commandInput'),commandResults=$('#commandResults');let visibleCommands=[];
function renderCommands(q=''){visibleCommands=commands.filter(c=>(c.title+' '+c.sub).toLowerCase().includes(q.toLowerCase()));commandResults.innerHTML=visibleCommands.length?`<div class="command-section">Results</div>${visibleCommands.map((c,i)=>`<button class="command-item ${i===0?'selected':''}" data-command="${i}"><span class="ci">${c.icon}</span><span class="ct"><strong>${c.title}</strong><small>${c.sub}</small></span>${c.key?`<kbd>${c.key}</kbd>`:''}</button>`).join('')}`:'<div class="command-empty">No matching command or blueprint.</div>'}
function openCommand(){renderCommands('');command.classList.add('open');commandBackdrop.classList.add('open');commandInput.value='';setTimeout(()=>commandInput.focus(),40)}function closeCommand(){command.classList.remove('open');commandBackdrop.classList.remove('open')}
$('#commandTrigger').onclick=openCommand;commandBackdrop.onclick=closeCommand;commandInput.oninput=e=>renderCommands(e.target.value);commandResults.onclick=e=>{const b=e.target.closest('[data-command]');if(!b)return;const c=visibleCommands[Number(b.dataset.command)];closeCommand();c.action()};

