let zenSeconds=50*60,zenTimer=null,zenPaused=false;function drawZen(){const m=Math.floor(zenSeconds/60),s=zenSeconds%60;$('#zenTime').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;document.title=$('#zenOverlay').classList.contains('open')?`${$('#zenTime').textContent} — Blueprint`:'Blueprint — Personal Operating System'}function startZen(){$('#zenOverlay').classList.add('open');zenSeconds=50*60;zenPaused=false;$('#zenPause').textContent='Pause';clearInterval(zenTimer);drawZen();zenTimer=setInterval(()=>{if(!zenPaused&&zenSeconds>0){zenSeconds--;drawZen()}if(zenSeconds===0){clearInterval(zenTimer);showToast('Focus block complete')}},1000)}function endZen(){clearInterval(zenTimer);$('#zenOverlay').classList.remove('open');document.title='Blueprint — Personal Operating System';showToast('Focus session ended')}
$('#startFocus').onclick=$('#focusMini').onclick=startZen;$('#zenPause').onclick=()=>{zenPaused=!zenPaused;$('#zenPause').textContent=zenPaused?'Resume':'Pause'};$('#zenDone').onclick=endZen;


// v7 — seasons + temporal atlas
let temporalHorizon=6;
const scenarioState={mornings:false,pause:false,recovery:false};
function seasonDays(){const end=new Date(`${profile.seasonEnd||defaultProfile.seasonEnd}T23:59:59`),now=new Date();return Math.max(0,Math.ceil((end-now)/86400000))}
function seasonDateLabel(){const d=new Date(`${profile.seasonEnd||defaultProfile.seasonEnd}T12:00:00`);return Number.isNaN(d.getTime())?'open-ended':`ends ${new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'}).format(d)}`}
function temporalItemHTML(item,primary=false){const attr=item.kind==='goal'?`data-temporal-goal="${item.id}"`:item.kind==='experiment'?`data-temporal-experiment="${item.id}"`:item.kind==='schedule'?`data-temporal-schedule="${item.id}"`:'data-page-jump="today"';return `<button class="trajectory-item ${primary?'primary':''}" ${attr}><span>${escapeHTML(item.meta)}</span><strong>${escapeHTML(item.title)}</strong><small>${escapeHTML(item.note||'')}</small></button>`}
function buildTemporalItems(){const active=experiments.filter(x=>x.status!=='archived');const high=[...goals].sort((a,b)=>(b.progress||0)-(a.progress||0));const now=[{kind:'focus',id:'focus',meta:'Primary outcome',title:profile.focus||defaultProfile.focus,note:'The concrete finish line your current week should make easier.'}];if(high[0])now.push({kind:'goal',id:high[0].id,meta:high[0].horizon,title:high[0].title,note:`${high[0].progress}% complete · ${high[0].metric}`});if(active[0])now.push({kind:'experiment',id:active[0].id,meta:`${active[0].category} experiment`,title:active[0].title,note:`Day ${experimentDay(active[0])} of ${active[0].duration} · evidence due now`});const emerging=[];high.slice(1,temporalHorizon===1?2:4).forEach(g=>emerging.push({kind:'goal',id:g.id,meta:g.horizon,title:g.title,note:`${g.progress}% complete · ${g.confidence==='watch'?'watch the load':'building momentum'}`}));active.slice(1,temporalHorizon===1?2:4).forEach(x=>emerging.push({kind:'experiment',id:x.id,meta:`${x.category} experiment`,title:x.title,note:`${experimentStats(x.id).logs} logs · ${x.success}`}));const later=[];schedules.slice(0,temporalHorizon===12?5:3).forEach(x=>later.push({kind:'schedule',id:x.id,meta:'Recurring rhythm',title:x.title,note:`${x.days.length}× / week · ${x.time} · ${x.duration} min`}));if(!later.length)later.push({kind:'focus',id:'space',meta:'Protected future',title:'Leave unclaimed capacity',note:'Not every open slot needs to become a commitment.'});return {now,emerging,later}}
function renderTemporalAtlas(){const el=$('#temporalAtlas');if(!el)return;const sets=buildTemporalItems();const lanes=[['now','Now','committed',sets.now],['emerging','Emerging','becoming likely',sets.emerging],['later','Later','protected from urgency',sets.later]];el.innerHTML=lanes.map(([cls,title,sub,items])=>`<section class="time-lane ${cls}"><div class="lane-head"><div><span>${sub}</span><strong>${title}</strong></div><em>${items.length} threads</em></div>${items.map((x,i)=>temporalItemHTML(x,cls==='now'&&i===0)).join('')||'<div class="archive-empty" style="min-height:170px"><div><p>Nothing needs to live here yet.</p></div></div>'}</section>`).join('')}
function renderTerrain(){const el=$('#terrainGrid');if(!el)return;const days=['M','T','W','T','F','S','S'],hours=[7,9,11,13,15,17,19];let html='<div></div>'+days.map(d=>`<div class="day">${d}</div>`).join('');const density=Array(7).fill(0);schedules.forEach(s=>s.days.forEach(d=>density[d]++));hours.forEach((h,hi)=>{html+=`<div class="hour">${String(h).padStart(2,'0')}</div>`;days.forEach((_,d)=>{const scheduled=schedules.some(x=>x.days.includes(d)&&Math.abs(Number(x.time.slice(0,2))-h)<=1);let heat=(h===9?0.68:h===11?0.56:h===13?0.34:h===15?0.23:h===7?0.36:0.14);if(dayMode==='recover')heat*=0.72;if(dayMode==='explore'&&h>=13)heat+=0.1;if(d>=5)heat*=0.62;html+=`<div class="terrain-cell ${scheduled?'scheduled':''}" style="--heat:${Math.min(.82,heat)}" title="${days[d]} ${String(h).padStart(2,'0')}:00${scheduled?' · recurring block':''}"></div>`})});el.innerHTML=html;const max=Math.max(...density),idx=density.indexOf(max);$('#crowdedDay').textContent=max?['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][idx]:'Unclaimed';$('#bestWindow').textContent=dayMode==='recover'?'10:00–12:00':dayMode==='explore'?'13:00–16:00':'09:00–11:00'}
function renderScenario(){let focus=68,space=54,strain=61;if(scenarioState.mornings){focus+=14;space-=4;strain+=3}if(scenarioState.pause){focus+=7;space+=12;strain-=8}if(scenarioState.recovery){focus+=4;space-=3;strain-=11}const clamp=n=>Math.max(0,Math.min(100,n));focus=clamp(focus);space=clamp(space);strain=clamp(strain);[['Focus',focus],['Space',space],['Strain',strain]].forEach(([k,v])=>{$(`#scenario${k}`).textContent=v;$(`#scenario${k}Bar`).style.width=`${v}%`})}
