function renderDrift(){const el=$('#driftList');if(!el)return;const items=[];if(goals.length>3)items.push(['◎','Split gravity',`${goals.length} active goals are competing for the same season. Consider pausing one.`,`${goals.length} goals`,'watch']);else items.push(['◎','Gravity contained',`${goals.length} active goals fit inside a legible field.`,`${goals.length} goals`,'clear']);const unlogged=experiments.filter(x=>experimentStats(x.id).logs===0);if(unlogged.length)items.push(['⌁','Invisible evidence',`${unlogged.length} experiment${unlogged.length>1?'s have':' has'} no check-ins yet. A trial without observations becomes a story.`,`${unlogged.length} unseen`,'watch']);else if(experiments.length)items.push(['⌁','Evidence visible','Every active experiment has at least one observation attached.','observable','clear']);if(schedules.length<2)items.push(['↯','Thin rails','Your direction is clearer than your recurring architecture. Add a rhythm only where repetition would reduce friction.',`${schedules.length} rails`,'watch']);else items.push(['↯','Rhythms established',`${schedules.length} recurring blocks are carrying intent into the week.`,`${schedules.length} rails`,'clear']);items.push(['⊘','Anti-goal',profile.seasonAnti||defaultProfile.seasonAnti,'active boundary','']);el.innerHTML=items.map(x=>`<div class="drift-item ${x[4]}"><i>${x[0]}</i><div><strong>${escapeHTML(x[1])}</strong><span>${escapeHTML(x[2])}</span></div><em>${escapeHTML(x[3])}</em></div>`).join('')}
function renderTemporal(){const d=seasonDays(),name=profile.seasonName||defaultProfile.seasonName,intent=profile.seasonIntent||defaultProfile.seasonIntent,anti=profile.seasonAnti||defaultProfile.seasonAnti;$('#seasonStripTitle')&&($('#seasonStripTitle').textContent=name);$('#seasonStripIntent')&&($('#seasonStripIntent').textContent=intent);$('#seasonStripDays')&&($('#seasonStripDays').textContent=d);$('#seasonTitle')&&($('#seasonTitle').textContent=name);$('#seasonIntent')&&($('#seasonIntent').textContent=intent);$('#seasonAntiGoal')&&($('#seasonAntiGoal').textContent=anti);$('#seasonDaysLeft')&&($('#seasonDaysLeft').textContent=d);$('#seasonEndLabel')&&($('#seasonEndLabel').textContent=seasonDateLabel());renderTemporalAtlas();renderTerrain();renderScenario();renderFutureNote();renderDrift()}
document.addEventListener('click',e=>{const h=e.target.closest('[data-horizon]');if(h){temporalHorizon=Number(h.dataset.horizon);$$('[data-horizon]').forEach(b=>b.classList.toggle('active',b===h));$('#horizonNarrative').textContent=temporalHorizon===1?'Only what deserves attention in the next seven days.':temporalHorizon===12?'A longer arc for sequencing without turning everything into “now.”':'What deserves attention across the next six weeks.';renderTemporalAtlas()}const sc=e.target.closest('[data-scenario]');if(sc){scenarioState[sc.dataset.scenario]=!scenarioState[sc.dataset.scenario];sc.classList.toggle('active',scenarioState[sc.dataset.scenario]);renderScenario()}const g=e.target.closest('[data-temporal-goal]');if(g){const item=goals.find(x=>x.id===g.dataset.temporalGoal);if(item)openCapture('Goal',item)}const x=e.target.closest('[data-temporal-experiment]');if(x)openDrawer(x.dataset.temporalExperiment);const sh=e.target.closest('[data-temporal-schedule]');if(sh){const item=schedules.find(x=>x.id===sh.dataset.temporalSchedule);if(item)openCapture('Schedule',item)}});
