function memoryAge(date){const days=Math.max(0,Math.floor((new Date()-new Date(date+'T12:00:00'))/86400000));return days===0?'today':days===1?'1 day ago':`${days} days ago`}
function renderMemory(){const grid=$('#memoryGrid');if(!grid)return;const visible=memories.filter(m=>memoryFilter==='all'||m.kind===memoryFilter).sort((a,b)=>b.resonance-a.resonance||String(b.createdAt).localeCompare(String(a.createdAt)));grid.innerHTML=visible.length?visible.map(m=>`<article class="card memory-card ${m.kind}" style="--resonance:${m.resonance}"><div class="memory-top"><span class="memory-kind">${escapeHTML(m.kind)}</span><span class="memory-age">${memoryAge(m.createdAt)}</span></div><h3>${escapeHTML(m.title)}</h3><p>${escapeHTML(m.text)}</p><div class="memory-source"><span>${escapeHTML(m.source||'Personal observation')}</span><span class="resonance" title="Resonance ${m.resonance}/5">${[1,2,3,4,5].map(i=>`<i class="${i<=m.resonance?'on':''}"></i>`).join('')}</span></div><div class="memory-actions"><button class="grow" data-grow-memory="${m.id}">+ resonate</button><button data-ritual-memory="${m.id}">make ritual</button><button data-edit-memory="${m.id}">edit</button><button class="compost" data-compost-memory="${m.id}">compost</button></div></article>`).join(''):`<div class="memory-empty"><strong>No memories in this layer yet.</strong><p>Plant an observation. If it keeps proving useful, let it earn more resonance instead of burying it beneath newer notes.</p><button class="solid-btn" data-capture-type="Memory" data-open-capture>Plant memory</button></div>`;
const seeds=memories.filter(m=>m.kind==='seed').length,blooms=memories.filter(m=>m.kind==='bloom'||m.resonance>=4).length;$('#memorySeedCount').textContent=seeds;$('#memoryBloomCount').textContent=blooms;$('#memoryRitualCount').textContent=installedProtocols.length;$('#memoryHeroCount').textContent=memories.length;$('#memoryNavCount')&&($('#memoryNavCount').textContent=memories.length);const first=memories.map(m=>new Date(m.createdAt+'T12:00:00')).sort((a,b)=>a-b)[0];$('#memoryGardenAge').textContent=first?`${Math.max(1,Math.floor((new Date()-first)/86400000)+1)}d`:'0d';renderEchoes();renderProtocols();renderEmergence()}
function renderEchoes(){const el=$('#echoGrid');if(!el)return;const latest=checkins.filter(c=>c.note).slice(-1)[0];const strongest=[...memories].sort((a,b)=>b.resonance-a.resonance)[0];const rhythm=schedules[0];const echoes=[
['Recent evidence',latest?.note||'No experiment observation has been written yet. The next check-in can become the first echo.',latest?`From ${experiments.find(x=>x.id===latest.experiment)?.title||'an experiment'}`:'Waiting for evidence'],
['Strongest memory',strongest?.text||'Plant a memory worth returning to.',strongest?`${strongest.title} · resonance ${strongest.resonance}/5`:'Garden empty'],
['Identity forming',rhythm?`“${rhythm.title}” is repeated ${rhythm.days.length}× each week. Repetition is quietly turning an intention into a default.`:'No personalized recurring schedule is carrying intent into the week yet.',rhythm?'From recurring architecture':'From the schedule']
];el.innerHTML=echoes.map(x=>`<article class="card echo-card"><span>${escapeHTML(x[0])}</span><blockquote>${escapeHTML(x[1])}</blockquote><footer>${escapeHTML(x[2])}</footer></article>`).join('')}
function renderProtocols(){const el=$('#protocolGrid');if(!el)return;el.innerHTML=protocolTemplates.map(p=>{const installed=installedProtocols.includes(p.id);return `<article class="card protocol-card ${installed?'installed':''}"><span>${escapeHTML(p.kind)}</span><h3>${escapeHTML(p.title)}</h3><p>${escapeHTML(p.copy)}</p><div class="protocol-steps">${p.steps.map(x=>`<i>${escapeHTML(x)}</i>`).join('')}</div><div class="protocol-foot"><small>${installed?'installed in schedule':`${p.schedule.days.length}× / week · ${p.schedule.time}`}</small><button data-protocol="${p.id}">${installed?'Remove':'Install'}</button></div></article>`}).join('')}
function renderEmergence(){const title=$('#emergenceTitle');if(!title)return;const best=[...memories].sort((a,b)=>b.resonance-a.resonance)[0];const logged=checkins.length;const rails=schedules.length;let score=Math.min(95,34+(best?.resonance||1)*8+Math.min(18,logged*2)+Math.min(12,rails*3));let label=score>78?'becoming durable':score>58?'forming':'faint';if(best){title.textContent=best.resonance>=4?`“${best.title}” is becoming a principle`:`“${best.title}” keeps resurfacing`;$('#emergenceCopy').textContent=best.resonance>=4?`This memory has high resonance. If it keeps changing decisions, consider turning it into a recurring ritual.`:`The idea has appeared more than once, but it still needs evidence before it earns more weight.`}else{$('#emergenceCopy').textContent='Plant observations and Blueprint will surface the ones that keep changing decisions.'}$('#emergenceBar').style.width=`${score}%`;$('#emergenceLabel').textContent=label}
function toggleProtocol(id){const p=protocolTemplates.find(x=>x.id===id);if(!p)return;const installed=installedProtocols.includes(id);if(installed){installedProtocols=installedProtocols.filter(x=>x!==id);schedules=schedules.filter(s=>s.protocolId!==id);showToast(`${p.title} removed`)}else{installedProtocols.push(id);if(!schedules.some(s=>s.protocolId===id))schedules.push({id:'protocol-'+id,title:p.schedule.title,notes:p.schedule.notes,days:[...p.schedule.days],time:p.schedule.time,duration:p.schedule.duration,category:p.schedule.category,protocolId:id});showToast(`${p.title} installed`)}store.set('bp-protocols-v8',installedProtocols);store.set('bp-schedules-v5',schedules);renderProtocols();renderSchedules();renderCalendar();renderMemory();renderConstellation();renderTemporal()}
