  explore:{title:'Explore',label:'explore · porous',narrative:'Leave deliberate room for surprise, research, and useful detours.',state:'Open curiosity',score:74,copy:'Your field is intentionally porous. Protect wandering time, but leave one breadcrumb that lets discovery become future action.',question:'What are you curious about even if it never becomes productive?',fragment:'“Discovery needs edges soft enough for the unexpected to enter.”'},
