function setDayMode(mode){if(!modeConfig[mode])mode='build';dayMode=mode;document.body.dataset.mode=mode;store.set('bp-mode-v6',mode);$$('[data-mode-choice]').forEach(b=>b.classList.toggle('active',b.dataset.modeChoice===mode));const c=modeConfig[mode];$('#modeTitle')&&($('#modeTitle').textContent=c.title);$('#modeNarrative')&&($('#modeNarrative').textContent=c.narrative);$('#modeChip span')&&($('#modeChip span').textContent=`${c.title} mode`);$('#orbitLabel')&&($('#orbitLabel').textContent=c.label);$('#fieldStateTitle')&&($('#fieldStateTitle').textContent=c.state);$('#fieldStateScore')&&($('#fieldStateScore').textContent=c.score);$('#fieldStateCopy')&&($('#fieldStateCopy').textContent=c.copy);$('#fieldQuestion')&&($('#fieldQuestion').textContent=c.question);$('#fieldFragment')&&($('#fieldFragment').textContent=c.fragment);renderThreads();renderTerrain()}
