function constellationPos(i,total,rx,ry,phase=-Math.PI/2){const a=phase+(Math.PI*2*i/Math.max(1,total));return {x:50+Math.cos(a)*rx,y:50+Math.sin(a)*ry}}
function renderConstellation(){const stage=$('#constellationStage');if(!stage)return;const gs=goals.slice(0,5),xs=experiments.filter(x=>x.status!=='archived').slice(0,6),ss=schedules.slice(0,6);const gp=gs.map((_,i)=>constellationPos(i,gs.length,27,25,-Math.PI/2));const outer=[...xs.map(x=>({kind:'experiment',item:x})),...ss.map(x=>({kind:'schedule',item:x}))];const op=outer.map((_,i)=>constellationPos(i,outer.length,43,40,-Math.PI/2+.34));let lines='';gp.forEach(p=>{lines+=`<line x1="500" y1="306" x2="${p.x*10}" y2="${p.y*6.12}"/>`});op.forEach((p,i)=>{const g=gp.length?gp[i%gp.length]:{x:50,y:50};lines+=`<line class="outer" x1="${g.x*10}" y1="${g.y*6.12}" x2="${p.x*10}" y2="${p.y*6.12}"/>`});const center=`<div class="constellation-center"><div><span>North star</span><strong>${escapeHTML(profile.northStar||defaultProfile.northStar)}</strong><small>${goals.length} gravity points · ${experiments.length+schedules.length} orbiting systems</small></div></div>`;const goalNodes=gs.map((g,i)=>`<button class="constellation-node goal" style="left:${gp[i].x}%;top:${gp[i].y}%" data-field-goal="${g.id}"><span>${escapeHTML(g.horizon)}</span><strong>${escapeHTML(g.title)}</strong></button>`).join('');const outerNodes=outer.map((o,i)=>{const p=op[i],title=o.item.title||'Recurring rhythm',meta=o.kind==='experiment'?o.item.category:(o.item.category||'Rhythm');return `<button class="constellation-node ${o.kind}" style="left:${p.x}%;top:${p.y}%" data-field-${o.kind}="${o.item.id}"><span>${escapeHTML(meta)}</span><strong>${escapeHTML(title)}</strong></button>`}).join('');stage.innerHTML=`<svg class="field-lines" viewBox="0 0 1000 612" preserveAspectRatio="none">${lines}</svg>${center}${goalNodes}${outerNodes}`;$('#fieldTimestamp').textContent=`${goals.length+experiments.length+schedules.length} live elements · ${modeConfig[dayMode].title.toLowerCase()} mode`;renderThreads()}
function renderThreads(){const wrap=$('#threadGrid');if(!wrap)return;const firstGoal=goals[0]?.title||'Your north star',firstExp=experiments[0]?.title||'your next experiment',firstSchedule=schedules[0]?.title||'protected time';const c=modeConfig[dayMode]||modeConfig.build;const items=[['Gravity → evidence',firstGoal,`Your strongest direction becomes more believable when ${firstExp} produces observable evidence.`],['Rhythm → identity',firstSchedule,`Repeated time blocks are quietly becoming part of how this workspace defines “normal.”`],['Mode → permission',c.title,dayMode==='recover'?'Today is allowed to optimize for capacity instead of visible output.':dayMode==='explore'?'Today can produce questions and fragments, not only finished artifacts.':dayMode==='connect'?'Today values alignment and conversation as real work.':'Today favors convergence: fewer threads, stronger finish lines.']];wrap.innerHTML=items.map(x=>`<article class="card thread-card"><span>${x[0]}</span><strong>${escapeHTML(x[1])}</strong><p>${escapeHTML(x[2])}</p><div class="thread-link"><i></i>active relationship</div></article>`).join('')}
