document.addEventListener('keydown',e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName);const altPages={1:'today',2:'plan',3:'lab',4:'reflect',5:'you'};if(!typing&&e.altKey&&altPages[e.key]){e.preventDefault();go(altPages[e.key])}else if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}else if(e.key==='Escape'){closeAtlas();closeCommand();closeCapture();closeCheckin();closeDrawer();if($('#zenOverlay').classList.contains('open'))endZen()}else if(!typing&&e.key.toLowerCase()==='g'){e.preventDefault();openAtlas()}else if(!typing&&e.key.toLowerCase()==='c'){openCapture()}else if(!typing&&e.altKey&&e.key.toLowerCase()==='m'){e.preventDefault();go('memory')}else if(!typing&&e.altKey&&e.key.toLowerCase()==='d'){e.preventDefault();go('compass')}else if(!typing&&e.key.toLowerCase()==='f'){startZen()}else if(command.classList.contains('open')&&e.key==='Enter'&&visibleCommands[0]){closeCommand();visibleCommands[0].action()}});


// v9 — Decision Architecture
const defaultPrinciples=[
{id:'p-attention',title:'Attention is a finite commons',body:'Protect the quality of attention before optimizing the quantity of output.',guardrail:'Do not schedule a second cognitively heavy block when the first one already consumes the best window.'},
{id:'p-evidence',title:'Evidence before identity',body:'Treat experiments as information, not proof of who you are.',guardrail:'Do not turn a three-day pattern into a permanent self-story.'},
{id:'p-space',title:'Leave room for emergence',body:'Useful plans contain negative space so new information can matter.',guardrail:'Keep at least one meaningful block per week intentionally unclaimed.'},
{id:'p-finish',title:'Finish before multiplying',body:'New possibility is cheap; durable completion is scarce.',guardrail:'Do not begin a second primary project while the current one is on its critical path.'}
];
