let consultedDecisionId=null;

function safeDateLabel(v){if(!v)return 'No review date';const d=new Date(v+'T12:00:00');return Number.isNaN(d.getTime())?'No review date':new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'}).format(d)}
function isReviewDue(d){return d.status==='open'&&d.reviewDate&&d.reviewDate<=todayISO}
function decisionDebt(){const open=decisions.filter(d=>d.status==='open');const due=open.filter(isReviewDue).length;if(due>=3||open.length>=6)return 'High';if(due>=1||open.length>=4)return 'Medium';return 'Low'}
function coherenceScore(){const p=Math.min(100,55+principles.length*5);const due=decisions.filter(isReviewDue).length;const open=decisions.filter(d=>d.status==='open').length;return Math.max(42,Math.min(96,p-due*7-Math.max(0,open-4)*3))}
function renderPrinciples(){const grid=$('#principleGrid');if(!grid)return;grid.innerHTML=principles.map((p,i)=>`<article class="card principle-card"><span class="principle-index">${String(i+1).padStart(2,'0')}</span><span class="tag">principle</span><h3>${escapeHTML(p.title)}</h3><p>${escapeHTML(p.body)}</p><div class="principle-guardrail">${escapeHTML(p.guardrail)}</div><div class="principle-actions"><button data-edit-principle="${p.id}">Edit</button><button data-delete-principle="${p.id}">Remove</button></div></article>`).join('')+`<button class="card add-principle" id="addPrinciple"><div><strong>＋ Add a principle</strong><p>Make a value operational by pairing it with a guardrail.</p></div></button>`;$('#principleCount').textContent=principles.length;$('#addPrinciple')?.addEventListener('click',()=>editPrinciple())}
function editPrinciple(id){const old=principles.find(p=>p.id===id);const title=prompt('Principle',old?.title||'');if(title===null||!title.trim())return;const body=prompt('What does it protect?',old?.body||'')??'';const guardrail=prompt('Operational guardrail',old?.guardrail||'')??'';const item={id:old?.id||'principle-'+Date.now(),title:title.trim(),body:body.trim()||'Define what this principle protects.',guardrail:guardrail.trim()||'Define the behavior this principle changes.'};const idx=principles.findIndex(p=>p.id===item.id);if(idx>=0)principles[idx]=item;else principles.push(item);store.set('bp-principles-v9',principles);renderDecisionArchitecture();showToast(old?'Principle updated':'Principle added')}
function renderCouncil(){const grid=$('#councilGrid');if(!grid)return;grid.innerHTML=council.map(c=>`<article class="card council-card" style="--council-color:${c.color}"><div class="council-sigil">${c.sigil}</div><span class="role">${escapeHTML(c.role)}</span><h3>${escapeHTML(c.name)}</h3><p>${escapeHTML(c.protects)}</p><div class="council-question">“${escapeHTML(c.question)}”</div><div class="council-actions"><button data-edit-council="${c.id}" style="margin-top:10px">Tune voice</button></div></article>`).join('')}
function editCouncil(id){const c=council.find(x=>x.id===id);if(!c)return;const name=prompt('Perspective name',c.name);if(name===null||!name.trim())return;const protects=prompt('What does this perspective protect?',c.protects)??c.protects;const question=prompt('Its defining question',c.question)??c.question;Object.assign(c,{name:name.trim(),protects:protects.trim(),question:question.trim()});store.set('bp-council-v9',council);renderDecisionArchitecture();showToast('Council voice tuned')}
function renderDecisions(){const list=$('#decisionList');if(!list)return;const sorted=[...decisions].sort((a,b)=>(a.status==='open'?0:1)-(b.status==='open'?0:1)||String(b.createdAt).localeCompare(String(a.createdAt)));list.innerHTML=sorted.length?sorted.map(d=>`<article class="card decision-entry"><div class="decision-top"><div><span class="tag">${escapeHTML(d.type)}</span><h3>${escapeHTML(d.title)}</h3></div><span class="confidence ${d.status==='open'?'high':'watch'}">${d.status}</span></div><p>${escapeHTML(d.context||'No context captured yet.')}</p><div class="decision-meta"><span class="${isReviewDue(d)?'live':''}">Review ${safeDateLabel(d.reviewDate)}</span><span>${escapeHTML(d.leaning||'No leaning yet')}</span></div><div class="decision-confidence"><div class="progress"><i style="width:${Math.max(0,Math.min(100,Number(d.conviction)||0))}%"></i></div><small>${d.conviction||0}% conviction</small></div><div class="decision-actions"><button data-consult-decision="${d.id}">Consult council</button><button data-toggle-decision="${d.id}">${d.status==='open'?'Close loop':'Reopen'}</button><button data-delete-decision="${d.id}">Delete</button></div></article>`).join(''):'<div class="card archive-empty"><div><div class="glyph">◈</div><h3>No decisions logged.</h3><p>Record choices you want future-you to be able to audit.</p></div></div>';const open=decisions.filter(d=>d.status==='open');$('#openDecisionCount').textContent=open.length;$('#decisionReviewCount').textContent=decisions.filter(isReviewDue).length;$('#choiceDebt').textContent=decisionDebt();$('#decisionNavCount')&&($('#decisionNavCount').textContent=open.length);renderDecisionPulse()}
function councilObservation(c,d){const type=d.type==='identity'?'identity-shaping':d.type==='sticky'?'costly to reverse':'safe enough to test';const conviction=Number(d.conviction)||0;const low=conviction<60;const fragments={builder:`Treat this as ${type}. Ask what concrete artifact, milestone, or cleared constraint exists two weeks after the choice.`,steward:`Price the choice in recovery and attention, not only hours. ${low?'Low conviction is a reason to preserve slack.':'High conviction still needs a capacity budget.'}`,explorer:`Look for the smallest version that preserves optionality. A reversible probe may reveal more than another round of abstract planning.`,witness:`Separate observed constraints from preferred narratives. Write down one piece of evidence that would make your current leaning wrong.`};return fragments[c.id]||`From the ${c.name} perspective: ${c.question}`}
function consultDecision(id){const d=decisions.find(x=>x.id===id);if(!d)return;consultedDecisionId=id;const panel=$('#consultationPanel');panel.innerHTML=`<div class="consultation-head"><div><span class="tag">council consultation</span><h3>${escapeHTML(d.title)}</h3><p>${escapeHTML(d.context||'No additional context captured.')}</p></div><span class="confidence high">${d.conviction}% conviction</span></div><div class="voice-stack">${council.map(c=>`<div class="voice"><div class="vmark">${c.sigil}</div><div><strong>${escapeHTML(c.name)} · ${escapeHTML(c.role)}</strong><p>${escapeHTML(councilObservation(c,d))}</p><small>Question: ${escapeHTML(c.question)}</small></div></div>`).join('')}</div><div class="principle-guardrail" style="margin-top:15px">Council output is a tension profile, not a verdict. Revisit the choice on ${safeDateLabel(d.reviewDate)} with new evidence.</div>`;panel.scrollIntoView({behavior:'smooth',block:'nearest'})}
function renderTensions(){const board=$('#tensionBoard');if(!board)return;const gs=goals.slice(0,4);const pairs=[];for(let i=0;i<gs.length;i++)for(let j=i+1;j<gs.length&&pairs.length<3;j++)pairs.push([gs[i],gs[j]]);if(!pairs.length){board.innerHTML='<div class="card archive-empty"><div><h3>Tension needs at least two goals.</h3><p>Create multiple directions and Compass will make their trade-offs visible.</p></div></div>';return}board.innerHTML=pairs.map(([a,b],i)=>{const balance=Math.max(15,Math.min(85,50+(Number(a.progress||0)-Number(b.progress||0))/3));const notes=['Both can be valid while competing for the same prime attention.','Progress in one may quietly consume recovery required by the other.','Sequence may resolve this tension better than compromise.'];return `<article class="card tension-card"><div class="tension-pair"><div class="tension-node"><strong>${escapeHTML(a.title)}</strong><span>${a.progress}% active</span></div><div class="tension-line" style="--balance:${balance}%"></div><div class="tension-node" style="text-align:right"><strong>${escapeHTML(b.title)}</strong><span>${b.progress}% active</span></div></div><h4>${['Attention','Capacity','Sequence'][i]||'Trade-off'} tension</h4><p>${notes[i]||notes[0]}</p><footer>No winner implied · make the constraint explicit</footer></article>`}).join('')}
function renderDecisionPulse(){const open=decisions.filter(d=>d.status==='open');const d=open.find(isReviewDue)||open[0];if(!d){$('#decisionPulseTitle')&&($('#decisionPulseTitle').textContent='No consequential choices are waiting.');$('#decisionPulseMeta')&&($('#decisionPulseMeta').textContent='Compass is quiet. Keep the calendar concrete.');return}$('#decisionPulseTitle')&&($('#decisionPulseTitle').textContent=d.title);$('#decisionPulseMeta')&&($('#decisionPulseMeta').textContent=`${d.conviction}% conviction · review ${safeDateLabel(d.reviewDate)} · ${d.type}`)}
function renderDecisionArchitecture(){renderPrinciples();renderCouncil();renderDecisions();renderTensions();$('#compassCoherence')&&($('#compassCoherence').textContent=coherenceScore())}

$('#decisionConviction')?.addEventListener('input',e=>{$('#decisionConvictionOut').textContent=e.target.value;$('#decisionConvictionLabel').textContent=e.target.value+'%'});
$('#decisionForm')?.addEventListener('submit',e=>{e.preventDefault();const title=$('#decisionTitle').value.trim();if(!title)return;decisions.unshift({id:'decision-'+Date.now(),title,context:$('#decisionContext').value.trim(),type:$('#decisionType').value,leaning:$('#decisionLeaning').value.trim(),conviction:Number($('#decisionConviction').value)||0,reviewDate:$('#decisionReviewDate').value,createdAt:todayISO,status:'open'});store.set('bp-decisions-v9',decisions);e.target.reset();$('#decisionConviction').value=65;$('#decisionConvictionOut').textContent='65';$('#decisionConvictionLabel').textContent='65%';renderDecisionArchitecture();showToast('Decision recorded')});
$('#jumpDecisionForm')?.addEventListener('click',()=>{$('#decisionJournalAnchor').scrollIntoView({behavior:'smooth'});setTimeout(()=>$('#decisionTitle').focus(),300)});
$('#consultLatestDecision')?.addEventListener('click',()=>{const d=decisions.find(x=>x.status==='open')||decisions[0];if(d)consultDecision(d.id);else showToast('Record a decision first')});
$('#resurfacePrinciple')?.addEventListener('click',()=>{if(!principles.length)return;const p=principles[Math.floor(Date.now()/1000)%principles.length];showToast(p.title)});
document.addEventListener('click',e=>{const ep=e.target.closest('[data-edit-principle]');if(ep)editPrinciple(ep.dataset.editPrinciple);const dp=e.target.closest('[data-delete-principle]');if(dp){principles=principles.filter(p=>p.id!==dp.dataset.deletePrinciple);store.set('bp-principles-v9',principles);renderDecisionArchitecture();showToast('Principle removed')}const ec=e.target.closest('[data-edit-council]');if(ec)editCouncil(ec.dataset.editCouncil);const cd=e.target.closest('[data-consult-decision]');if(cd)consultDecision(cd.dataset.consultDecision);const td=e.target.closest('[data-toggle-decision]');if(td){const d=decisions.find(x=>x.id===td.dataset.toggleDecision);if(d){d.status=d.status==='open'?'closed':'open';store.set('bp-decisions-v9',decisions);renderDecisionArchitecture();showToast(d.status==='open'?'Decision reopened':'Decision loop closed')}}const dd=e.target.closest('[data-delete-decision]');if(dd){decisions=decisions.filter(x=>x.id!==dd.dataset.deleteDecision);store.set('bp-decisions-v9',decisions);renderDecisionArchitecture();showToast('Decision removed')}});
renderDecisionArchitecture();



