pageNames.commons='Commons';
const defaultPeople=[
{id:'maya',name:'Maya',role:'Creative collaborator',relation:'core',lastTouch:'2026-09-21',context:'Shared product thinking and a standing habit of sending rough work before it feels finished.'},
{id:'sam',name:'Sam',role:'Training partner',relation:'active',lastTouch:'2026-09-19',context:'Race preparation, long-run coordination, and honest recovery checks.'},
{id:'lena',name:'Lena',role:'Mentor',relation:'active',lastTouch:'2026-09-12',context:'Useful outside perspective on what deserves to become public work.'},
{id:'theo',name:'Theo',role:'Research peer',relation:'light',lastTouch:'2026-09-03',context:'Occasional evidence swaps and synthesis feedback around Atlas.'}
];
const defaultCommitments=[
{id:'com-maya',personId:'maya',title:'Send the interaction prototype before polishing the copy',direction:'owe',dueDate:'2026-09-24',goalId:'body',note:'Rough is useful here; the promise is about visibility, not perfection.',status:'open',createdAt:'2026-09-21'},
{id:'com-sam',personId:'sam',title:'Confirm Saturday long-run route',direction:'shared',dueDate:'2026-09-25',goalId:'endurance',note:'Choose a route that allows an early exit if recovery is poor.',status:'open',createdAt:'2026-09-20'},
{id:'com-theo',personId:'theo',title:'Atlas source review',direction:'waiting',dueDate:'2026-09-28',goalId:'body',note:'Waiting for comments on the evidence taxonomy before the synthesis pass.',status:'open',createdAt:'2026-09-18'}
];
let people=store.get('bp-people-v10',[]);
let commitments=store.get('bp-commitments-v10',[]);
let commonsFilter='all',selectedPersonId='';
function commonsToday(){return ymd(new Date())}
function dateDiffDays(a,b){const aa=new Date(a+'T12:00:00'),bb=new Date(b+'T12:00:00');return Math.round((bb-aa)/86400000)}
function personById(id){return people.find(p=>p.id===id)}
function goalById(id){return goals.find(g=>g.id===id)}
function relationRadius(rel){return rel==='core'?18:rel==='active'?31:43}
function commonsInitials(name){return initials(name||'?')}
function dueState(c){if(c.status==='done'||!c.dueDate)return {label:c.status==='done'?'closed':'no date',overdue:false};const d=dateDiffDays(commonsToday(),c.dueDate);if(d<0)return {label:`${Math.abs(d)}d overdue`,overdue:true};if(d===0)return {label:'today',overdue:false};if(d===1)return {label:'tomorrow',overdue:false};return {label:`in ${d}d`,overdue:false}}
function needsTouch(p){if(!p.lastTouch)return true;return dateDiffDays(p.lastTouch,commonsToday())>=14}
function populateCommonsForms(){
  const personSelect=$('#commitmentPerson');if(personSelect)personSelect.innerHTML=people.length?people.map(p=>`<option value="${p.id}">${escapeHTML(p.name)} · ${escapeHTML(p.role||'person')}</option>`).join(''):'<option value="">Add a person first</option>';
  const goalSelect=$('#commitmentGoal');if(goalSelect)goalSelect.innerHTML='<option value="">No goal link</option>'+goals.map(g=>`<option value="${g.id}">${escapeHTML(g.title)}</option>`).join('');
}
function renderRelationField(){const field=$('#relationField');if(!field)return;const cx=50,cy=50;let lines='',nodes='';const groups={core:people.filter(p=>p.relation==='core'),active:people.filter(p=>p.relation==='active'),light:people.filter(p=>p.relation==='light')};Object.entries(groups).forEach(([rel,arr])=>{const r=relationRadius(rel);arr.forEach((p,i)=>{const phase=rel==='core'?-Math.PI/2:rel==='active'?-Math.PI/2+.5:-Math.PI/2+.25;const a=phase+(Math.PI*2*i/Math.max(1,arr.length));const x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*(r*.86);const dx=x-cx,dy=y-cy,len=Math.sqrt(dx*dx+dy*dy),angle=Math.atan2(dy,dx)*180/Math.PI;lines+=`<i class="relation-line" style="width:${len}%;transform:rotate(${angle}deg)"></i>`;nodes+=`<button class="person-node ${selectedPersonId===p.id?'active':''}" style="left:${x}%;top:${y}%" data-select-person="${p.id}"><div><i>${commonsInitials(p.name)}</i><strong>${escapeHTML(p.name)}</strong></div><small>${escapeHTML(p.role||rel)}${needsTouch(p)?' · reconnect':''}</small></button>`})});field.innerHTML=`<div class="relation-ring light"></div><div class="relation-ring active"></div><div class="relation-ring core"></div><span class="relation-ring-label light">light</span><span class="relation-ring-label active">active</span><span class="relation-ring-label core">core</span>${lines}<div class="self-node"><div><span>self</span><strong>${escapeHTML(profile.name?.trim()||'You')}</strong></div></div>${nodes}`;$('#relationFieldMeta').textContent=`${people.length} people · ${people.filter(needsTouch).length} may need a touch`}
function renderPeople(){const grid=$('#peopleGrid');if(!grid)return;grid.innerHTML=people.length?people.map(p=>{const open=commitments.filter(c=>c.personId===p.id&&c.status==='open').length;return `<article class="card person-card"><div class="person-head"><div class="person-avatar">${commonsInitials(p.name)}</div><div><h3>${escapeHTML(p.name)}</h3><span class="role">${escapeHTML(p.role||'Person')}</span></div></div><p>${escapeHTML(p.context||'No shared context yet.')}</p><div class="person-foot"><span class="relation-badge">${escapeHTML(p.relation)} · ${open} open</span><div class="person-actions"><button data-touch-person="${p.id}">${needsTouch(p)?'touch':'touched'}</button><button data-edit-person="${p.id}">edit</button><button data-delete-person="${p.id}">remove</button></div></div></article>`}).join(''):`<div class="card archive-empty" style="grid-column:1/-1"><div><div class="glyph">∞</div><h3>Your commons is empty.</h3><p>Add people only when shared expectations deserve a place in the plan.</p></div></div>`}
function filteredCommitments(){return commitments.filter(c=>(commonsFilter==='all'||c.direction===commonsFilter)&&(!selectedPersonId||c.personId===selectedPersonId))}
function renderLedger(){const list=$('#commitmentList');if(!list)return;const items=filteredCommitments().sort((a,b)=>(a.status==='open'?0:1)-(b.status==='open'?0:1)||String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999')));$('#ledgerTitle').textContent=selectedPersonId?`Loops with ${personById(selectedPersonId)?.name||'person'}`:'Open shared loops';list.innerHTML=items.length?items.map(c=>{const p=personById(c.personId),g=goalById(c.goalId),due=dueState(c);return `<div class="commitment-row ${c.status==='done'?'done':''}"><span class="direction ${c.direction}">${c.direction==='owe'?'I owe':c.direction==='ask'?'I asked':c.direction==='waiting'?'Waiting':'Shared'}</span><div class="commitment-main"><strong>${escapeHTML(c.title)}</strong><small>${escapeHTML(p?.name||'Unassigned')}${g?` · ${escapeHTML(g.title)}`:''}${c.note?` · ${escapeHTML(c.note)}`:''}</small></div><div class="commitment-due ${due.overdue?'overdue':''}"><strong>${escapeHTML(due.label)}</strong><small>${c.dueDate||'open horizon'}</small></div><div class="commitment-actions"><button data-toggle-commitment="${c.id}">${c.status==='done'?'reopen':'done'}</button><button data-nudge-commitment="${c.id}">${c.direction==='waiting'?'nudge':'remind'}</button><button data-edit-commitment="${c.id}">edit</button></div></div>`}).join(''):'<div class="ledger-empty">No shared loops match this view.</div>';$$('[data-commons-filter]').forEach(b=>b.classList.toggle('active',b.dataset.commonsFilter===commonsFilter))}
function renderCommonsSignals(){const wrap=$('#commonsSignals');if(!wrap)return;const open=commitments.filter(c=>c.status==='open'),unlinked=open.filter(c=>!c.goalId),waiting=open.filter(c=>c.direction==='waiting'),reconnect=people.filter(needsTouch);const signals=[['Boundary check',unlinked.length?`${unlinked.length} shared ${unlinked.length===1?'loop is':'loops are'} not connected to an active goal.`:'Every open commitment has a visible strategic context.',unlinked.length?'Unlinked does not mean wrong—only make the trade-off explicit.':'Shared promises and private direction are currently legible.'],['Silent blockers',waiting.length?`${waiting.length} item${waiting.length===1?' is':'s are'} waiting on someone else.`:'No external dependency is quietly blocking the system.',waiting.length?'A waiting loop needs a follow-up date, fallback, or release condition.':'The critical path is mostly under your control.'],['Relationship horizon',reconnect.length?`${reconnect.length} relationship${reconnect.length===1?' has':'s have'} gone quiet for two weeks or more.`:'No active relationship is drifting into accidental silence.',reconnect.length?'Reconnect because the relationship matters, not to clear a metric.':'Attention to people is not currently being deferred by the system.']];wrap.innerHTML=signals.map(x=>`<article class="card commons-signal-card"><span>signal</span><h3>${escapeHTML(x[0])}</h3><p>${escapeHTML(x[1])}</p><footer>${escapeHTML(x[2])}</footer></article>`).join('')}
function renderCommonsWeather(){const open=commitments.filter(c=>c.status==='open'),waiting=open.filter(c=>c.direction==='waiting'),overdue=open.filter(c=>dueState(c).overdue),dueSoon=open.filter(c=>c.dueDate&&dateDiffDays(commonsToday(),c.dueDate)>=0&&dateDiffDays(commonsToday(),c.dueDate)<=7),owe=open.filter(c=>c.direction==='owe');let headline='The commons is clear.',body='Shared expectations are visible and none are exerting unusual pressure.',icon='∞';if(overdue.length){headline='A promise is crossing its boundary.';body=`${overdue.length} shared ${overdue.length===1?'loop is':'loops are'} overdue. Renegotiate explicitly rather than letting silence become the plan.`;icon='↯'}else if(waiting.length>=2){headline='External dependencies are accumulating.';body='Several threads are waiting on other people. Add fallback paths before the waiting becomes a hidden critical path.';icon='⌁'}else if(owe.length>=3){headline='Your private calendar is carrying public weight.';body='Several people are now planning around promises you made. Protect those blocks differently from optional intentions.';icon='◇'}$('#weatherIcon').textContent=icon;$('#weatherHeadline').textContent=headline;$('#weatherBody').textContent=body;$('#commonsWeatherTitle').textContent=headline;$('#commonsWeatherCopy').textContent=body;$('#commonsPeopleCount').textContent=people.length;$('#commonsOpenCount').textContent=open.length;$('#commonsWaitingCount').textContent=waiting.length;$('#commonsDueCount').textContent=dueSoon.length;$('#commonsNavCount')&&($('#commonsNavCount').textContent=open.length);$('#weatherSignals').innerHTML=`<div class="weather-signal"><span>You owe</span><strong>${owe.length} promise${owe.length===1?'':'s'} currently visible to someone else.</strong></div><div class="weather-signal"><span>Waiting</span><strong>${waiting.length} external dependenc${waiting.length===1?'y':'ies'} on the board.</strong></div><div class="weather-signal"><span>Reconnection</span><strong>${people.filter(needsTouch).length} relationship${people.filter(needsTouch).length===1?'':'s'} may deserve an intentional touch.</strong></div>`;renderCommonsPulse()}
function renderCommonsPulse(){const open=commitments.filter(c=>c.status==='open'),due=open.filter(c=>c.dueDate&&dateDiffDays(commonsToday(),c.dueDate)>=0&&dateDiffDays(commonsToday(),c.dueDate)<=3),waiting=open.filter(c=>c.direction==='waiting');if(!$('#commonsPulseTitle'))return;if(due.length){$('#commonsPulseTitle').textContent=`${due.length} shared ${due.length===1?'loop':'loops'} entering the near horizon.`;$('#commonsPulseMeta').textContent='These are promises or dependencies that now affect someone else’s plan.'}else if(waiting.length){$('#commonsPulseTitle').textContent=`${waiting.length} external ${waiting.length===1?'dependency is':'dependencies are'} still open.`;$('#commonsPulseMeta').textContent='Decide whether to follow up, create a fallback, or release the dependency.'}else{$('#commonsPulseTitle').textContent='Shared reality is quiet.';$('#commonsPulseMeta').textContent='No near-term promise or external dependency is demanding attention.'}}
