function uniquePush(arr,item){if(!item)return;if(!arr.some(x=>x.id===item.id))arr.push(structuredClone(item))}
function installStarterKit(id,{silent=false}={}){const kit=starterKits.find(k=>k.id===id);if(!kit)return;if(installedKits.includes(id)){if(!silent)showToast(`${kit.title} is already installed`);return}uniquePush(goals,kit.goal);(kit.metrics||[]).forEach(x=>uniquePush(customMetrics,x));if(kit.experiment)uniquePush(experiments,kit.experiment);if(kit.schedule)uniquePush(schedules,kit.schedule);installedKits.push(id);store.set('bp-goals-v5',goals);store.set('bp-custom-metrics-v12',customMetrics);store.set('bp-experiments-v5',experiments);store.set('bp-schedules-v5',schedules);store.set('bp-template-installs-v13',installedKits);renderGoals();renderMetrics();renderExperiments();renderSchedules();renderCalendar();renderV12Hubs();renderLibrary();renderSetupState();renderConstellation?.();renderTemporal?.();if(!silent)showToast(`${kit.title} installed — everything is editable`)}
function renderLibrary(){const grid=$('#templateGrid');if(!grid)return;grid.innerHTML=starterKits.map(k=>`<button class="kit-card ${installedKits.includes(k.id)?'installed':''}" style="--kit:${k.color}" data-install-kit="${k.id}"><span class="kit-domain">${escapeHTML(k.domain)}</span><h3>${escapeHTML(k.title)}</h3><p>${escapeHTML(k.desc)}</p><div class="kit-foot"><div class="kit-adds">${k.adds.map(a=>`<span>${escapeHTML(a)}</span>`).join('')}</div><span class="kit-state">${installedKits.includes(k.id)?'installed':'install →'}</span></div></button>`).join('');const picker=$('#setupKitPicker');if(picker)picker.innerHTML=`<button data-setup-kit=""><strong>Start blank</strong><span>Use only the areas and operating style you selected.</span></button>`+starterKits.map(k=>`<button data-setup-kit="${k.id}" class="${setupTemplate===k.id?'active':''}"><strong>${escapeHTML(k.title)}</strong><span>${escapeHTML(k.domain)} · ${escapeHTML(k.adds.slice(0,2).join(' + '))}</span></button>`).join('')}
function setupCompletionScore(){let score=0;if(onboarding.completed)score+=45;if((onboarding.domains||[]).length)score+=20;if(goals.length)score+=15;if(customMetrics.length)score+=10;if(schedules.length)score+=10;return Math.min(100,score)}
function renderSetupState(){const title=$('#setupStripTitle'),copy=$('#setupStripCopy'),chips=$('#setupStripChips'),btn=$('#openSetup');if(!title)return;const domains=onboarding.domains||[];if(onboarding.completed){title.textContent='Blueprint is tuned — and still editable';copy.textContent=`${onboarding.structure||'balanced'} structure · ${onboarding.reviewDay||'Friday'} review rhythm · ${setupCompletionScore()}% initial architecture`;btn.textContent='Retune →';chips.innerHTML=(domains.length?domains:['Open-ended']).slice(0,5).map(x=>`<i>${escapeHTML(x)}</i>`).join('')+(installedKits.length?`<i>${installedKits.length} starter ${installedKits.length===1?'kit':'kits'}</i>`:'')}else{title.textContent='Tune Blueprint around your life';copy.textContent='Choose the areas you care about, how much structure you want, and an optional starting architecture.';btn.textContent='Set up →';chips.innerHTML='<i>3 steps</i><i>fully editable</i><i>about 2 minutes</i>'}}
function syncSetupUI(){$$('[data-setup-step]').forEach(s=>s.classList.toggle('active',Number(s.dataset.setupStep)===setupStep));$$('#setupProgress i').forEach((i,n)=>i.classList.toggle('on',n<setupStep));$$('[data-domain]').forEach(b=>b.classList.toggle('active',setupDomains.includes(b.dataset.domain)));$$('[data-structure]').forEach(b=>b.classList.toggle('active',b.dataset.structure===setupStructure));$$('[data-setup-kit]').forEach(b=>b.classList.toggle('active',b.dataset.setupKit===setupTemplate));$('#setupBack').style.visibility=setupStep===1?'hidden':'visible';$('#setupNext').textContent=setupStep===3?'Finish setup':'Continue'}
function openSetupModal(){setupStep=1;setupDomains=[...(onboarding.domains||[])];setupStructure=onboarding.structure||'balanced';setupTemplate=onboarding.templateId||'';$('#setupName').value=profile.name||'';$('#setupReviewDay').value=onboarding.reviewDay||'Friday';renderLibrary();syncSetupUI();$('#setupBackdrop').classList.add('open');$('#setupModal').classList.add('open')}
