function finishSetup(){onboarding={completed:true,domains:[...setupDomains],structure:setupStructure,reviewDay:$('#setupReviewDay').value||'Friday',templateId:setupTemplate};const n=$('#setupName').value.trim();if(n)profile.name=n;profile.domains=[...setupDomains];profile.systemDepth=setupStructure;profile.reviewDay=onboarding.reviewDay;store.set('bp-onboarding-v13',onboarding);store.set('bp-profile-v5',profile);if(setupTemplate)installStarterKit(setupTemplate,{silent:true});renderSetupState();renderWorkspace();renderLibrary();closeSetupModal();showToast('Blueprint tuned to your starting context')}
