function pulseToday(){return ymd(new Date())}
function renderPulse(){if(!$('#pulseEnergy'))return;const today=pulseToday(),existing=dailyPulses.find(x=>x.date===today);if(existing){$('#pulseEnergy').value=existing.energy;$('#pulseFocus').value=existing.focus;$('#pulseMood').value=existing.mood;$('#pulseNote').value=existing.note||'';$('#pulseStatus').textContent='logged today'}else{$('#pulseStatus').textContent='not logged today'}['Energy','Focus','Mood'].forEach(k=>{$('#pulse'+k+'Out').textContent=$('#pulse'+k).value});const recent=[...dailyPulses].sort((a,b)=>a.date.localeCompare(b.date)).slice(-7),bars=$('#pulseBars');if(bars){bars.innerHTML=recent.length?recent.map(x=>{const avg=(Number(x.energy)+Number(x.focus)+Number(x.mood))/3;return `<i title="${escapeHTML(x.date)} · ${avg.toFixed(1)}/5" style="height:${Math.round(16+avg*10)}px"></i>`}).join(''):'<i style="height:16px;opacity:.2"></i><i style="height:22px;opacity:.18"></i><i style="height:18px;opacity:.16"></i><i style="height:26px;opacity:.14"></i><i style="height:20px;opacity:.12"></i><i style="height:24px;opacity:.1"></i><i style="height:18px;opacity:.08"></i>';const all=recent.flatMap(x=>[Number(x.energy),Number(x.focus),Number(x.mood)]).filter(Number.isFinite),avg=all.length?all.reduce((a,b)=>a+b,0)/all.length:null;$('#pulseAverage').textContent=avg?`${avg.toFixed(1)} / 5`:'waiting for signal';$('#pulseHistoryCopy').textContent=recent.length>=3?`${recent.length} recent check-ins. Look for direction and context, not a “good” score.`:'Your first few check-ins will create a quiet seven-day pattern here.'}}
['Energy','Focus','Mood'].forEach(k=>$('#pulse'+k)?.addEventListener('input',e=>$('#pulse'+k+'Out').textContent=e.target.value));$('#savePulse')?.addEventListener('click',()=>{const item={date:pulseToday(),energy:Number($('#pulseEnergy').value),focus:Number($('#pulseFocus').value),mood:Number($('#pulseMood').value),note:$('#pulseNote').value.trim()};const i=dailyPulses.findIndex(x=>x.date===item.date);if(i>=0)dailyPulses[i]=item;else dailyPulses.push(item);store.set('bp-daily-pulse-v13',dailyPulses);renderPulse();showToast('Daily pulse saved')});

