function v14DateOnly(d){return ymd(d)}
function v14RollingDays(){const out=[];const now=new Date();now.setHours(12,0,0,0);for(let i=6;i>=0;i--){const d=new Date(now);d.setDate(now.getDate()-i);out.push(d)}return out}
function v14PulseAvg(p){return p?([Number(p.energy),Number(p.focus),Number(p.mood)].reduce((a,b)=>a+(Number.isFinite(b)?b:0),0)/3):0}
function v14InRollingWeek(value){if(!value)return false;const t=new Date(value);if(Number.isNaN(t.getTime()))return false;const start=v14RollingDays()[0];start.setHours(0,0,0,0);const end=new Date();end.setHours(23,59,59,999);return t>=start&&t<=end}
function v14RoutineCount(){const dates=new Set(v14RollingDays().map(v14DateOnly)),designs=store.get('bp-day-design-v27',{})||{};return [...dates].filter(d=>!!designs[d]?.updatedAt).length}
function v14WeekStats(){const days=v14RollingDays();const pulses=days.map(d=>dailyPulses.find(x=>x.date===v14DateOnly(d))||null);const valid=pulses.filter(Boolean);const pulseAvg=valid.length?valid.reduce((a,p)=>a+v14PulseAvg(p),0)/valid.length:0;const focusAvg=valid.length?valid.reduce((a,p)=>a+Number(p.focus||0),0)/valid.length:0;const energyAvg=valid.length?valid.reduce((a,p)=>a+Number(p.energy||0),0)/valid.length:0;const moodAvg=valid.length?valid.reduce((a,p)=>a+Number(p.mood||0),0)/valid.length:0;const recentCheckins=(checkins||[]).filter(x=>v14InRollingWeek(x.date));const routineCount=v14RoutineCount();const load=(goals?.length||0)+(experiments?.filter(x=>x.status!=='complete').length||0)+(schedules?.length||0);return {days,pulses,valid,pulseAvg,focusAvg,energyAvg,moodAvg,recentCheckins,routineCount,load}}
function v14DayEvidence(date,pulse){const dateKey=v14DateOnly(date);const exp=(checkins||[]).filter(x=>String(x.date||'').slice(0,10)===dateKey).length;const designs=store.get('bp-day-design-v27',{})||{};const routines=designs[dateKey]?.updatedAt?1:0;const signal=pulse?Math.round(v14PulseAvg(pulse)/5*100):8;return {exp,routines,signal}}
function v14WeekCell(date,pulse){const ev=v14DayEvidence(date,pulse),today=v14DateOnly(date)===v14DateOnly(new Date());const day=date.toLocaleDateString('en-US',{weekday:'short'}).slice(0,2);const num=date.getDate();const label=pulse?`${v14PulseAvg(pulse).toFixed(1)} pulse`:(ev.exp?`${ev.exp} lab log${ev.exp===1?'':'s'}`:ev.routines?'day shaped':'quiet');return `<div class="week-day ${today?'today':''}" style="--signal:${Math.max(8,ev.signal)}%"><span><b>${day}</b><em>${num}</em></span><strong>${pulse?v14PulseAvg(pulse).toFixed(1):'·'}</strong><div class="week-fill"><i></i></div><em>${escapeHTML(label)}</em></div>`}
function v14Adaptive(stats){if(stats.valid.length<2)return {title:'The week is still becoming legible.',copy:`${stats.valid.length} daily ${stats.valid.length===1?'pulse':'pulses'} captured. Keep the evidence lightweight until a direction appears.`,posture:'Create signal before complexity.',reason:'A few honest check-ins are more useful than adding another dashboard.'};const first=stats.valid.slice(0,Math.max(1,Math.floor(stats.valid.length/2))),last=stats.valid.slice(Math.max(1,Math.floor(stats.valid.length/2)));const avg=(arr,key)=>arr.length?arr.reduce((a,p)=>a+Number(p[key]||0),0)/arr.length:0;const fd=avg(last,'focus')-avg(first,'focus'),ed=avg(last,'energy')-avg(first,'energy');if(ed<-0.55)return {title:'Capacity softened while the system stayed active.',copy:`Energy averaged ${stats.energyAvg.toFixed(1)}/5 across ${stats.valid.length} check-ins. Treat that as context, not failure: reduce optional load before adding a new improvement project.`,posture:'Protect recovery before expansion.',reason:'The current signal suggests capacity deserves more weight than ambition next week.'};if(fd>0.45)return {title:'Attention is becoming more available.',copy:`Focus rose across the week while you captured ${stats.recentCheckins.length} experiment ${stats.recentCheckins.length===1?'observation':'observations'}. Preserve the conditions around your cleanest blocks before changing too much.`,posture:'Repeat the conditions around good focus.',reason:'When something improves, replication is usually more informative than immediate optimization.'};if(stats.recentCheckins.length===0&&experiments.filter(x=>x.status==='active').length)return {title:'Experiments are running faster than evidence.',copy:`You have ${experiments.filter(x=>x.status==='active').length} active experiments but no observations in the last seven days. Consider shrinking the logging burden before judging the protocols.`,posture:'Make one experiment easier to observe.',reason:'An experiment without evidence becomes a story you can tell either way.'};return {title:'The week looks steady enough to interpret slowly.',copy:`Pulse averaged ${stats.pulseAvg.toFixed(1)}/5 with ${stats.routineCount} routine completions and ${stats.recentCheckins.length} experiment logs. No single signal needs to dominate the story.`,posture:'Keep one thing stable; vary one thing.',reason:'A cleaner next cycle will make cause and context easier to separate.'}}
function renderV14Weekprint(){const stats=v14WeekStats(),cells=stats.days.map((d,i)=>v14WeekCell(d,stats.pulses[i])).join('');$('#todayWeekprint')&&($('#todayWeekprint').innerHTML=cells);$('#reviewWeekprint')&&($('#reviewWeekprint').innerHTML=cells);const adaptive=v14Adaptive(stats);if($('#weekSignalTitle')){$('#weekSignalTitle').textContent=adaptive.title;$('#weekSignalCopy').textContent=adaptive.copy;$('#weekSignalBadge').textContent=stats.valid.length?`${stats.valid.length}/7 days observed`:'waiting for evidence';$('#weekPulseStat').textContent=stats.valid.length?`${stats.pulseAvg.toFixed(1)} / 5`:'—';$('#weekPulseMeta').textContent=stats.valid.length?`focus ${stats.focusAvg.toFixed(1)} · energy ${stats.energyAvg.toFixed(1)}`:'energy · focus · mood';$('#weekCheckinStat').textContent=`${stats.recentCheckins.length} ${stats.recentCheckins.length===1?'log':'logs'}`;$('#weekRoutineStat').textContent=String(stats.routineCount);$('#weekLoadStat').textContent=String(stats.load)}if($('#reviewWeekTitle')){$('#reviewWeekTitle').textContent=stats.valid.length>=3?'This is the shape your last seven days left behind.':'The first useful pattern is still forming.';$('#reviewWeekCopy').textContent=stats.valid.length>=3?`Across ${stats.valid.length} observed days, pulse averaged ${stats.pulseAvg.toFixed(1)}/5. The visualization is evidence density—not a performance score.`:'Keep the system light. A few honest observations are enough to make the next review more specific.';$('#adaptiveBriefTitle').textContent=adaptive.title;$('#adaptiveBriefCopy').textContent=adaptive.copy;$('#nextWeekPosture').textContent=adaptive.posture;$('#nextWeekReason').textContent=adaptive.reason;const max=Math.max(1,stats.valid.length,stats.recentCheckins.length,stats.routineCount);$('#evidenceStack').innerHTML=[['Daily pulses',stats.valid.length,7],['Experiment logs',stats.recentCheckins.length,Math.max(3,stats.recentCheckins.length)],['Routine completions',stats.routineCount,Math.max(7,stats.routineCount)],['Active load',stats.load,Math.max(10,stats.load)]].map(([label,val,den])=>`<div class="evidence-row"><span>${label}</span><strong>${val}</strong><i style="--w:${Math.min(100,Math.round(val/den*100))}%"><b></b></i></div>`).join('')}}
function v14WeekId(){const d=new Date();d.setHours(12,0,0,0);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return v14DateOnly(d)}
function renderWeeklySynthesis(){const id=v14WeekId(),existing=weeklySyntheses.find(x=>x.week===id);if($('#weeklyKeep')){$('#weeklyKeep').value=existing?.keep||'';$('#weeklyChange').value=existing?.change||'';$('#weeklyExplore').value=existing?.explore||'';$('#synthesisStatus').textContent=existing?'saved this week':'not saved'}const root=$('#weekReviewHistory');if(!root)return;const rows=[...weeklySyntheses].sort((a,b)=>b.week.localeCompare(a.week));root.innerHTML=rows.length?rows.map(x=>{const d=new Date(x.week+'T12:00:00');const summary=[x.keep&&`Keep: ${x.keep}`,x.change&&`Change: ${x.change}`,x.explore&&`Explore: ${x.explore}`].filter(Boolean).join(' · ');return `<article class="card week-review-item"><div class="week-review-date"><div><strong>${d.getDate()}</strong><span>${d.toLocaleDateString('en-US',{month:'short'})}</span></div></div><div><h3>Week of ${d.toLocaleDateString('en-US',{month:'long',day:'numeric'})}</h3><p>${escapeHTML(summary||'A weekly synthesis was saved without notes.')}</p><div class="week-review-tags"><span>${x.stats?.designDays??x.stats?.routines??0} day designs</span><span>${x.stats?.checkins||0} observations</span><span>${x.stats?.load||0} active structures</span></div></div><div class="week-review-actions"><button data-promote-week="${x.week}">→ Memory</button><button data-delete-week="${x.week}">Delete</button></div></article>`}).join(''):'<div class="card archive-empty"><div><div class="glyph">↻</div><h3>No weekprints saved yet.</h3><p>Your first Keep / Change / Explore synthesis will become the beginning of a longitudinal story.</p></div></div>'}
$('#weeklySynthesisForm')?.addEventListener('submit',e=>{e.preventDefault();const id=v14WeekId(),stats=v14WeekStats(),item={week:id,keep:$('#weeklyKeep').value.trim(),change:$('#weeklyChange').value.trim(),explore:$('#weeklyExplore').value.trim(),savedAt:new Date().toISOString(),stats:{pulseDays:stats.valid.length,pulseAvg:stats.pulseAvg,checkins:stats.recentCheckins.length,designDays:stats.routineCount,routines:stats.routineCount,load:stats.load}};const i=weeklySyntheses.findIndex(x=>x.week===id);if(i>=0)weeklySyntheses[i]=item;else weeklySyntheses.push(item);store.set('bp-weekly-syntheses-v14',weeklySyntheses);renderWeeklySynthesis();showToast('Learning note saved')});
$('#pinNextWeekBrief')?.addEventListener('click',()=>{const a=v14Adaptive(v14WeekStats());inbox.unshift({title:a.posture,meta:`Next-week intention · ${a.reason}`,type:'Reflection'});store.set('bp-inbox-v2',inbox);renderInbox();showToast('Next-week intention pinned')});
document.addEventListener('click',e=>{const p=e.target.closest('[data-promote-week]');if(p){const w=weeklySyntheses.find(x=>x.week===p.dataset.promoteWeek);if(!w)return;const text=[w.keep&&`Keep: ${w.keep}`,w.change&&`Change: ${w.change}`,w.explore&&`Explore: ${w.explore}`].filter(Boolean).join(' · ');if(!text){showToast('Add a synthesis before promoting it');return}if(!memories.some(m=>m.id==='week-'+w.week))memories.unshift({id:'week-'+w.week,title:`Week of ${w.week}`,text,kind:'lesson',resonance:3,source:'Weekly synthesis',createdAt:w.week});store.set('bp-memories-v8',memories);renderMemory?.();showToast('Weekprint promoted to Memory')}const d=e.target.closest('[data-delete-week]');if(d){weeklySyntheses=weeklySyntheses.filter(x=>x.week!==d.dataset.deleteWeek);store.set('bp-weekly-syntheses-v14',weeklySyntheses);renderWeeklySynthesis();showToast('Weekprint deleted')}});
const renderPulseV14=renderPulse;renderPulse=function(){renderPulseV14();renderV14Weekprint?.()};
const renderRoutinesV14=renderRoutines;renderRoutines=function(){renderRoutinesV14();renderV14Weekprint?.()};
const renderCheckinsV14=renderCheckins;renderCheckins=function(){renderCheckinsV14();renderV14Weekprint?.()};
commands.splice(Math.max(0,commands.length-2),0,{icon:'↻',title:'Read this week',sub:'Weekprint · signals · Keep / Change / Explore',action:()=>go('review')});
const resetWorkspaceV14=$('#resetWorkspace').onclick;$('#resetWorkspace').onclick=()=>{storage.removeItem('bp-weekly-syntheses-v14');weeklySyntheses=[];resetWorkspaceV14();renderV14Weekprint();renderWeeklySynthesis()};
renderV14Weekprint();renderWeeklySynthesis();


// v15 — shape-aware goal journeys
function saveGoalJourneys(){store.set('bp-goal-journeys-v15',goalJourneys);renderGoals()}
function ensureJourney(id){if(!goalJourneys[id])goalJourneys[id]={reviewCadence:'Monthly',nextReview:'',milestones:[],evidence:[],links:{metrics:[],experiments:[],schedules:[]}};goalJourneys[id].milestones=goalJourneys[id].milestones||[];goalJourneys[id].evidence=goalJourneys[id].evidence||[];goalJourneys[id].links=goalJourneys[id].links||{metrics:[],experiments:[],schedules:[]};['metrics','experiments','schedules'].forEach(k=>goalJourneys[id].links[k]=goalJourneys[id].links[k]||[]);return goalJourneys[id]}
function journeyLinksHTML(goal,j,shape){const groups=[['metrics','Metrics',customMetrics],['experiments','Experiments',experiments],['schedules','Rhythms',schedules]];return groups.map(([key,label,items])=>`<div class="journey-link-group"><span>${label}</span><div class="journey-chip-row">${items.length?items.map(x=>`<button class="journey-link-chip ${(j.links[key]||[]).includes(x.id)?'active':''}" data-journey-link="${key}" data-link-id="${x.id}" data-goal-id="${goal.id}">${escapeHTML(x.title)}</button>`).join(''):`<em style="font-size:8px;color:var(--faint)">No ${label.toLowerCase()} yet.</em>`}</div></div>`).join('')}
function journeyMilestonesHTML(goal,j){return j.milestones.length?j.milestones.map(m=>`<div class="journey-row ${m.done?'done':''}"><button class="check" data-journey-milestone-toggle="${m.id}" data-goal-id="${goal.id}">${m.done?'✓':'·'}</button><div><strong>${escapeHTML(m.title)}</strong><small>${m.date?`Target ${v15DateLabel(m.date)}`:'No date attached'}${m.done&&m.doneAt?` · closed ${v15DateLabel(m.doneAt)}`:''}</small></div><button class="remove" data-journey-milestone-delete="${m.id}" data-goal-id="${goal.id}">×</button></div>`).join(''):'<div style="font-size:8px;color:var(--faint);padding:8px 2px">No milestones yet. Add only the checkpoints that change what you do next.</div>'}
function journeyEvidenceHTML(goal,j){return j.evidence.length?[...j.evidence].reverse().map(x=>`<div class="evidence-row-v15"><header><span>${escapeHTML(x.kind||'Observation')}</span><time>${v15DateLabel(x.date)}</time></header><p>${escapeHTML(x.text)}</p><footer><button data-journey-evidence-delete="${x.id}" data-goal-id="${goal.id}">remove</button></footer></div>`).join(''):'<div style="font-size:8px;color:var(--faint);padding:8px 2px">No direct evidence yet. Record behavior, results, friction, or a change in understanding.</div>'}
function openGoalJourney(id){const goal=goals.find(g=>g.id===id);if(!goal)return;const j=ensureJourney(id),shape=goalShapeCopy(goal.kind),sig=goalJourneySignal(goal,j);drawerBody.innerHTML=`<div style="--journey-accent:${shape.accent}"><div class="eyebrow">${shape.label} journey · ${escapeHTML(goal.domain||'Personal')}</div><h2 class="drawer-title">${escapeHTML(goal.title)}</h2><p class="drawer-desc">${escapeHTML(goal.desc)}</p><div class="goal-proof"><span>Proof model</span><h3>${escapeHTML(shape.question)}</h3><p>${escapeHTML(shape.proof)}</p></div><div class="goal-journey-meta"><div><span>Current signal</span><strong>${escapeHTML(sig.value)}</strong></div><div><span>Evidence</span><strong>${j.evidence.length} entries</strong></div><div><span>Connected systems</span><strong>${(j.links.metrics||[]).length+(j.links.experiments||[]).length+(j.links.schedules||[]).length} linked</strong></div></div><div class="journey-section"><div class="journey-section-head"><h4>Review architecture</h4><span>Choose when this goal deserves interpretation.</span></div><div class="journey-review"><label>Cadence<select id="journeyReviewCadence" data-goal-id="${goal.id}"><option ${j.reviewCadence==='Weekly'?'selected':''}>Weekly</option><option ${j.reviewCadence==='Monthly'?'selected':''}>Monthly</option><option ${j.reviewCadence==='Quarterly'?'selected':''}>Quarterly</option><option ${j.reviewCadence==='Seasonal'?'selected':''}>Seasonal</option><option ${j.reviewCadence==='As needed'?'selected':''}>As needed</option></select></label><label>Next review<input id="journeyNextReview" data-goal-id="${goal.id}" type="date" value="${escapeHTML(j.nextReview||'')}"></label></div><div class="journey-review-note">Reviews are checkpoints for changing the plan. They do not need to produce a score.</div></div><div class="journey-section"><div class="journey-section-head"><h4>Milestones</h4><span>${j.milestones.filter(x=>x.done).length}/${j.milestones.length} closed</span></div><form class="journey-form" id="journeyMilestoneForm" data-goal-id="${goal.id}"><input id="journeyMilestoneTitle" placeholder="A checkpoint that changes the next move" required><input id="journeyMilestoneDate" type="date"><button>Add</button></form><div class="journey-list">${journeyMilestonesHTML(goal,j)}</div></div><div class="journey-section"><div class="journey-section-head"><h4>Evidence journal</h4><span>Behavior · result · friction · insight</span></div><form class="journey-form evidence" id="journeyEvidenceForm" data-goal-id="${goal.id}"><select id="journeyEvidenceKind"><option>Observation</option><option>Win</option><option>Friction</option><option>Decision</option><option>Character evidence</option></select><textarea id="journeyEvidenceText" placeholder="What happened that changes how you understand this goal?" required></textarea><button>Add evidence</button></form><div class="journey-list">${journeyEvidenceHTML(goal,j)}</div></div><div class="journey-section"><div class="journey-section-head"><h4>Connected system</h4><span>Link only what actually supports or measures this goal.</span></div><div class="journey-links">${journeyLinksHTML(goal,j,shape)}</div></div><div class="drawer-actions"><button class="solid-btn" data-edit-goal="${goal.id}">Edit goal</button><button class="soft-btn" data-page-jump="review">Open Reflect</button></div></div>`;drawer.classList.add('open');drawerBackdrop.classList.add('open')}
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-goal]'),del=e.target.closest('[data-delete-goal]');if(edit||del)return;const open=e.target.closest('[data-goal-open-button],[data-goal-open]');if(open){const id=open.dataset.goalOpenButton||open.dataset.goalOpen;openGoalJourney(id);return}const link=e.target.closest('[data-journey-link]');if(link){const j=ensureJourney(link.dataset.goalId),key=link.dataset.journeyLink,id=link.dataset.linkId,arr=j.links[key];const i=arr.indexOf(id);i>=0?arr.splice(i,1):arr.push(id);saveGoalJourneys();openGoalJourney(link.dataset.goalId);return}const toggle=e.target.closest('[data-journey-milestone-toggle]');if(toggle){const j=ensureJourney(toggle.dataset.goalId),m=j.milestones.find(x=>x.id===toggle.dataset.journeyMilestoneToggle);if(m){m.done=!m.done;m.doneAt=m.done?ymd(new Date()):'';saveGoalJourneys();openGoalJourney(toggle.dataset.goalId)}return}const md=e.target.closest('[data-journey-milestone-delete]');if(md){const j=ensureJourney(md.dataset.goalId);j.milestones=j.milestones.filter(x=>x.id!==md.dataset.journeyMilestoneDelete);saveGoalJourneys();openGoalJourney(md.dataset.goalId);return}const ed=e.target.closest('[data-journey-evidence-delete]');if(ed){const j=ensureJourney(ed.dataset.goalId);j.evidence=j.evidence.filter(x=>x.id!==ed.dataset.journeyEvidenceDelete);saveGoalJourneys();openGoalJourney(ed.dataset.goalId);return}})
document.addEventListener('submit',e=>{if(e.target.id==='journeyMilestoneForm'){e.preventDefault();const id=e.target.dataset.goalId,j=ensureJourney(id),title=$('#journeyMilestoneTitle').value.trim();if(!title)return;j.milestones.push({id:'milestone-'+Date.now(),title,date:$('#journeyMilestoneDate').value,done:false,doneAt:''});saveGoalJourneys();openGoalJourney(id)}if(e.target.id==='journeyEvidenceForm'){e.preventDefault();const id=e.target.dataset.goalId,j=ensureJourney(id),text=$('#journeyEvidenceText').value.trim();if(!text)return;j.evidence.push({id:'evidence-'+Date.now(),kind:$('#journeyEvidenceKind').value,text,date:ymd(new Date())});saveGoalJourneys();openGoalJourney(id)}})
document.addEventListener('change',e=>{if(e.target.id==='journeyReviewCadence'){const j=ensureJourney(e.target.dataset.goalId);j.reviewCadence=e.target.value;saveGoalJourneys();showToast('Review cadence saved')}if(e.target.id==='journeyNextReview'){const j=ensureJourney(e.target.dataset.goalId);j.nextReview=e.target.value;saveGoalJourneys();showToast('Next review saved')}})
// Keep journey data tidy when goals are removed.
document.addEventListener('click',e=>{const del=e.target.closest('[data-delete-goal]');if(del&&goalJourneys[del.dataset.deleteGoal]){delete goalJourneys[del.dataset.deleteGoal];store.set('bp-goal-journeys-v15',goalJourneys)}})
const resetWorkspaceV15=$('#resetWorkspace').onclick;$('#resetWorkspace').onclick=()=>{storage.removeItem('bp-goal-journeys-v15');goalJourneys={};resetWorkspaceV15();renderGoals()}
commands.splice(Math.max(0,commands.length-2),0,{icon:'◎',title:'Open goal journeys',sub:'Evidence · milestones · reviews · connected systems',action:()=>go('goals')});
renderGoals();



// v16 — connected impact loop
let experimentImpact=store.get('bp-experiment-impact-v16',{});
let experimentReviews=store.get('bp-experiment-reviews-v16',[]);
let metricLogs=store.get('bp-metric-logs-v16',{});
let activeExperimentDecision='continue';
let metricLogTarget='';
const v16DefaultImpact={sleep:{goalId:'endurance',metricIds:['m-sleep','m-focus']},phone:{goalId:'attention',metricIds:['m-focus','m-deep']},caffeine:{goalId:'endurance',metricIds:['m-sleep']}};
function ensureImpact(id){if(!experimentImpact[id]){const reverse=goals.find(g=>(ensureJourney(g.id).links.experiments||[]).includes(id));experimentImpact[id]={goalId:reverse?.id||v16DefaultImpact[id]?.goalId||'',metricIds:[...(v16DefaultImpact[id]?.metricIds||[])]}};experimentImpact[id].metricIds=experimentImpact[id].metricIds||[];return experimentImpact[id]}
function saveImpact(){store.set('bp-experiment-impact-v16',experimentImpact);renderImpactSystem();renderGoals()}
function metricNumber(v){const n=parseFloat(String(v??'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:null}
function metricSeries(id){const m=customMetrics.find(x=>x.id===id),logs=[...(metricLogs[id]||[])].slice(-10);const vals=logs.map(x=>metricNumber(x.value)).filter(x=>x!==null);const cur=metricNumber(m?.value);if(cur!==null&&(vals.length===0||vals[vals.length-1]!==cur))vals.push(cur);return vals.slice(-10)}
function sparklineHTML(id){const vals=metricSeries(id);if(!vals.length)return '<div class="sparkline"><i style="--h:18%"></i><i style="--h:18%"></i><i style="--h:18%"></i></div>';const lo=Math.min(...vals),hi=Math.max(...vals),span=Math.max(1,hi-lo);return `<div class="sparkline">${vals.map(v=>`<i style="--h:${18+Math.round((v-lo)/span*78)}%"></i>`).join('')}</div>`}
function metricTrend(id){const vals=metricSeries(id),m=customMetrics.find(x=>x.id===id);if(vals.length<2)return {label:'baseline forming',delta:'—'};const a=vals[0],b=vals[vals.length-1],d=b-a;const sign=d>0?'+':'';return {label:d===0?'flat in recent logs':`${d>0?'up':'down'} across recent logs`,delta:`${sign}${Number(d.toFixed(2))}${m?.unit?' '+m.unit:''}`}}
function v16RecentCheckins(expId,days=14){const cutoff=Date.now()-days*86400000;return checkins.filter(x=>{if(x.experiment!==expId)return false;const raw=x.date||x.createdAt||'';const t=/^\d{4}-\d{2}-\d{2}$/.test(raw)?new Date(raw+'T12:00:00').getTime():new Date(raw).getTime();return Number.isFinite(t)&&t>=cutoff})}
function latestExperimentReview(id){return [...experimentReviews].reverse().find(x=>x.experimentId===id)}
function experimentDecisionDue(exp){const day=experimentDay(exp),last=latestExperimentReview(exp.id);if(exp.status==='stopped')return false;if(last&&Date.now()-new Date(last.createdAt).getTime()<7*86400000)return false;return day>=Math.max(3,Math.ceil(exp.duration*.5))||experimentStats(exp.id).logs>=4}
function impactStatus(exp){const imp=ensureImpact(exp.id),goal=goals.find(g=>g.id===imp.goalId),mets=imp.metricIds.map(id=>customMetrics.find(m=>m.id===id)).filter(Boolean);return {imp,goal,mets}}
function goalNarrative(g){const j=ensureJourney(g.id),linkedExps=experiments.filter(x=>ensureImpact(x.id).goalId===g.id),recentLogs=linkedExps.reduce((n,x)=>n+v16RecentCheckins(x.id,14).length,0),evidence=j.evidence.length,reviews=linkedExps.map(x=>latestExperimentReview(x.id)).filter(Boolean);if(g.kind==='target'){if(g.progress>=75&&recentLogs)return {title:'Outcome is moving and the evidence loop is active.',copy:`${g.progress}% reported progress · ${recentLogs} recent experiment observations · ${evidence} direct goal notes.`};if(g.progress>=45&&!recentLogs)return {title:'The outcome moved, but the evidence loop is thin.',copy:'Add one linked signal or experiment before increasing activity. The next useful question is what is actually causing movement.'};return {title:'The target still needs a sharper feedback loop.',copy:`${linkedExps.length} linked experiments · ${evidence} direct observations. Keep the next milestone more concrete than the ambition.`}}if(g.kind==='character'){return evidence?{title:'Character is being tracked through behavior, not identity claims.',copy:`${evidence} pieces of behavioral evidence are attached. Recent experiment observations: ${recentLogs}.`}:{title:'The character goal is still mostly an intention.',copy:'Record one concrete action that would count as evidence—especially when the easier choice was available.'}}if(g.kind==='system'){const rhythms=(j.links.schedules||[]).length;return rhythms?{title:'The system has rails; now watch whether they reduce friction.',copy:`${rhythms} linked rhythm${rhythms===1?'':'s'} · ${recentLogs} recent observations · ${evidence} goal notes.`}:{title:'This system goal has no recurring rail yet.',copy:'Link one repeatable rhythm or protocol before asking the system to become automatic.'}}return evidence?{title:'The direction has enough evidence to deserve interpretation.',copy:`${evidence} aligned choices are documented. Use the next review to decide whether this direction is becoming more or less relevant.`}:{title:'The direction is legible, but its lived evidence is still sparse.',copy:'Capture choices that either reinforce or contradict the direction. Contradictory evidence is useful.'}}
function goalMovementPoint(g){const j=ensureJourney(g.id),linked=experiments.filter(x=>ensureImpact(x.id).goalId===g.id),recent=linked.reduce((n,x)=>n+v16RecentCheckins(x.id,7).length,0),sched=(j.links.schedules||[]).length,metricLinks=new Set([...(j.links.metrics||[]),...linked.flatMap(x=>ensureImpact(x.id).metricIds||[])]).size,attention=Math.min(100,15+recent*13+sched*17+metricLinks*8);let movement;if(g.kind==='target')movement=Math.max(8,Math.min(100,Number(g.progress)||0));else if(g.kind==='character')movement=Math.min(100,10+j.evidence.length*17+recent*8);else if(g.kind==='system')movement=Math.min(100,15+sched*22+j.evidence.length*10+recent*5);else movement=Math.min(100,12+j.evidence.length*15+(v15ReviewDue(j)?0:8));return {attention,movement}}
function renderMovementMap(){const root=$('#movementPlot');if(!root)return;root.querySelectorAll('.movement-dot').forEach(x=>x.remove());const pts=goals.slice(0,7).map(g=>({g,...goalMovementPoint(g)}));pts.forEach(({g,attention,movement})=>{const shape=goalShapeCopy(g.kind),b=document.createElement('button');b.type='button';b.className='movement-dot';b.dataset.short=g.title;b.dataset.goalOpen=g.id;b.style.setProperty('--x',Math.max(.05,Math.min(.95,attention/100)));b.style.setProperty('--y',Math.max(.05,Math.min(.95,movement/100)));b.style.setProperty('--dot',shape.accent);b.setAttribute('aria-label',`${g.title}: attention ${attention}, movement ${movement}`);root.appendChild(b)});const heavy=pts.filter(p=>p.attention>=60&&p.movement<45),aligned=pts.filter(p=>p.attention>=45&&p.movement>=45);if($('#movementVerdict')){if(heavy.length){$('#movementVerdict').textContent=`${heavy.length} goal${heavy.length===1?' is':'s are'} receiving more attention than visible movement.`;$('#movementVerdictMeta').textContent='That can be normal during setup or learning. Use the linked experiment review to decide whether to continue, adjust, or reduce effort.'}else if(aligned.length){$('#movementVerdict').textContent=`${aligned.length} goal${aligned.length===1?' has':'s have'} both attention and visible movement.`;$('#movementVerdictMeta').textContent='Protect the conditions producing evidence before adding another commitment.'}else{$('#movementVerdict').textContent='The system is still building enough connected evidence.';$('#movementVerdictMeta').textContent='Link experiments and metrics to goals, then log observations. The map will become more diagnostic over time.'}}}
function renderImpactBrief(){const root=$('#impactBriefStats');if(!root)return;const linked=experiments.filter(x=>ensureImpact(x.id).goalId).length,withMetrics=experiments.filter(x=>ensureImpact(x.id).metricIds.length).length,decisions=experimentReviews.length,due=experiments.filter(experimentDecisionDue).length;root.innerHTML=`<div class="impact-stat"><span>Experiments linked</span><strong>${linked}/${experiments.length}</strong><small>trials with a goal destination</small></div><div class="impact-stat"><span>Signals linked</span><strong>${withMetrics}</strong><small>experiments with at least one metric</small></div><div class="impact-stat"><span>Decisions saved</span><strong>${decisions}</strong><small>review history retained</small></div><div class="impact-stat"><span>Reviews ready</span><strong>${due}</strong><small>mature enough to interpret</small></div>`;if($('#impactBriefCopy'))$('#impactBriefCopy').textContent=linked===experiments.length&&experiments.length?'Every active experiment has a destination. Keep the signals small enough that the review can actually change a decision.':`${Math.max(0,experiments.length-linked)} experiment${experiments.length-linked===1?' still needs':'s still need'} a goal link. Unlinked activity is harder to evaluate when the protocol ends.`}
function renderImpactMap(){const root=$('#impactChainList');if(!root)return;root.innerHTML=experiments.length?experiments.map(exp=>{const {goal,mets}=impactStatus(exp),st=experimentStats(exp.id),rev=latestExperimentReview(exp.id);return `<article class="impact-chain ${goal?'':'unlinked'}"><button class="impact-chain-node" data-detail="${exp.id}"><span>Experiment</span><strong>${escapeHTML(exp.title)}</strong><small>${st.logs} logs · day ${experimentDay(exp)}/${exp.duration}</small></button><div class="impact-chain-arrow">→</div><div class="impact-chain-node"><span>Goal</span><strong>${goal?escapeHTML(goal.title):'No destination yet'}</strong><small>${goal?escapeHTML(goal.domain||'Personal'):'Open experiment to link'}</small></div><div class="impact-chain-arrow metrics-arrow">→</div><div class="impact-chain-node metrics-node"><span>Signals</span><strong>${mets.length?mets.map(m=>escapeHTML(m.title)).join(' · '):'No linked metric'}</strong><small>${rev?`${rev.decision} · ${v15DateLabel(rev.date)}`:'No review decision yet'}</small></div></article>`}).join(''):'<div class="empty-personal"><strong>No experiments yet.</strong><p>Create one when a real question is worth testing.</p></div>';
 const q=$('#impactQueueList');if(!q)return;const items=[];experiments.filter(x=>!ensureImpact(x.id).goalId).forEach(x=>items.push({kind:'Unlinked',title:x.title,copy:'This trial has no goal destination yet, so its result may be hard to act on.',id:x.id}));experiments.filter(experimentDecisionDue).forEach(x=>items.push({kind:'Review ready',title:x.title,copy:`Day ${experimentDay(x)} of ${x.duration} · ${experimentStats(x.id).logs} observations. Enough evidence may exist to make a provisional decision.`,id:x.id}));q.innerHTML=items.length?items.slice(0,5).map(x=>`<div class="impact-queue-item"><span><b>${x.kind}</b><em>${x.kind==='Review ready'?'interpret':'connect'}</em></span><strong>${escapeHTML(x.title)}</strong><p>${escapeHTML(x.copy)}</p><button data-detail="${x.id}">Open experiment →</button></div>`).join(''):'<div class="impact-queue-item"><strong>No urgent experiment decisions.</strong><p>Keep observing until a link, signal, or decision genuinely needs attention.</p></div>'}
function renderExperimentReviewBoard(){const root=$('#experimentReviewBoard');if(!root)return;const rows=[...experimentReviews].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));$('#experimentReviewCount').textContent=`${rows.length} decision${rows.length===1?'':'s'}`;root.innerHTML=rows.length?rows.slice(0,8).map(r=>{const exp=experiments.find(x=>x.id===r.experimentId);return `<article class="review-decision-card"><header><div><span>${escapeHTML(r.decision)}</span><strong>${escapeHTML(exp?.title||r.experimentTitle||'Experiment')}</strong></div><small>${v15DateLabel(r.date)}</small></header><p>${escapeHTML(r.reason||'No reason recorded.')}</p><footer><small>${r.nextAction?`Next: ${escapeHTML(r.nextAction)}`:'No next action pinned'}</small><button data-detail="${r.experimentId}">Open →</button></footer></article>`}).join(''):'<div class="empty-personal" style="grid-column:1/-1"><strong>No experiment decisions saved yet.</strong><p>When a trial reaches a useful checkpoint, record Continue, Adjust, or Stop—and the evidence behind it.</p></div>'}
function trendCardsHTML(ids){return ids.length?`<div class="linked-trends">${ids.slice(0,4).map(id=>{const m=customMetrics.find(x=>x.id===id);if(!m)return'';const t=metricTrend(id);return `<div class="trend-card"><span>${escapeHTML(m.title)}</span><strong>${escapeHTML(m.value||'—')} ${escapeHTML(m.unit||'')}</strong>${sparklineHTML(id)}<small>${escapeHTML(t.label)}</small></div>`}).join('')}</div>`:'<div style="font-size:8px;color:var(--faint);margin-top:8px">No metric linked yet. A useful experiment usually needs only one or two signals.</div>'}
function experimentReviewHistoryHTML(id){const rows=experimentReviews.filter(x=>x.experimentId===id).slice(-5).reverse();return rows.length?`<div class="experiment-review-history">${rows.map(r=>`<div class="experiment-review-row"><header><strong>${escapeHTML(r.decision)}</strong><time>${v15DateLabel(r.date)}</time></header><p>${escapeHTML(r.reason||'No reason recorded.')}</p><small>${r.nextAction?`Next: ${escapeHTML(r.nextAction)}`:'No next action'}</small></div>`).join('')}</div>`:'<div style="font-size:8px;color:var(--faint);margin-top:8px">No review decision yet. The first decision can be provisional.</div>'}
const openDrawerV16Base=openDrawer;
openDrawer=function(key){const exp=experiments.find(x=>x.id===key);if(!exp){openDrawerV16Base(key);return}const st=experimentStats(exp.id),day=experimentDay(exp),protocol=String(exp.protocol||'').split(/\n+/).filter(Boolean),{imp,goal,mets}=impactStatus(exp),latest=latestExperimentReview(exp.id);activeExperimentDecision=latest?.decision||'continue';drawerBody.innerHTML=`<div><div class="eyebrow">Experiment · ${escapeHTML(exp.category)}</div><h2 class="drawer-title">${escapeHTML(exp.title)}</h2><p class="drawer-desc">${escapeHTML(exp.hypothesis)}</p><div class="mini-grid"><div class="mini"><span>Day</span><strong>${day} / ${exp.duration}</strong></div><div class="mini"><span>Adherence</span><strong>${st.logs?st.adherent+'%':'—'}</strong></div><div class="mini"><span>Evidence</span><strong>${st.logs} logs</strong></div></div><div class="impact-configuration"><span>Impact chain</span><h3>What is this experiment supposed to move?</h3><p>Link one goal and only the signals that would genuinely change your interpretation.</p><div class="impact-select"><label>Goal<select id="impactGoalSelect" data-experiment-id="${exp.id}"><option value="">No goal linked</option>${goals.map(g=>`<option value="${g.id}" ${imp.goalId===g.id?'selected':''}>${escapeHTML(g.title)}</option>`).join('')}</select></label><label>Review posture<select id="impactReviewPosture"><option>Evidence first</option><option>Behavior first</option><option>Outcome first</option></select></label></div><div class="impact-metric-picks">${customMetrics.map(m=>`<button type="button" class="${imp.metricIds.includes(m.id)?'active':''}" data-impact-metric="${m.id}" data-experiment-id="${exp.id}">${escapeHTML(m.title)}</button>`).join('')}</div>${trendCardsHTML(imp.metricIds)}</div><div class="detail-section"><h4>Success criterion</h4><div class="detail-box"><p>${escapeHTML(exp.success)}</p></div></div><div class="detail-section"><h4>Protocol</h4><div class="detail-box">${protocol.length?protocol.map((m,i)=>`<div class="milestone"><i>${i+1}</i><div><strong>${escapeHTML(m)}</strong><small>Personal protocol</small></div></div>`).join(''):'<p>No protocol steps yet.</p>'}</div></div><div class="experiment-review-form"><span>Decision checkpoint</span><h3>What should happen because of the evidence?</h3><p>Choose a provisional decision. You can reverse it when new evidence arrives.</p><div class="decision-picker"><button type="button" data-exp-decision="continue" class="${activeExperimentDecision==='continue'?'active':''}">Continue</button><button type="button" data-exp-decision="adjust" class="${activeExperimentDecision==='adjust'?'active':''}">Adjust</button><button type="button" data-exp-decision="stop" class="${activeExperimentDecision==='stop'?'active':''}">Stop</button></div><div class="review-fields"><label>Reason<textarea id="experimentReviewReason" placeholder="What evidence makes this decision reasonable right now?"></textarea></label><label>Evidence that mattered<textarea id="experimentReviewEvidence" placeholder="A pattern, observation, or signal—not just a feeling."></textarea></label></div><label style="display:block;font-size:7px;color:var(--faint);text-transform:uppercase;letter-spacing:.08em;margin-top:8px">Next action<input id="experimentNextAction" placeholder="What should change in the real system next?"></label><label class="review-pin"><input type="checkbox" id="experimentPinNext" checked> Pin the next action to Inbox</label><button class="solid-btn review-save" data-save-experiment-review="${exp.id}">Save decision</button>${experimentReviewHistoryHTML(exp.id)}</div><div class="drawer-actions"><button class="solid-btn" data-checkin="${exp.id}">Log check-in</button><button class="soft-btn" data-edit-experiment="${exp.id}">Edit experiment</button><button class="soft-btn" data-delete-experiment="${exp.id}">Delete</button></div></div>`;drawer.classList.add('open');drawerBackdrop.classList.add('open')}
const openGoalJourneyV16Base=openGoalJourney;
openGoalJourney=function(id){openGoalJourneyV16Base(id);const g=goals.find(x=>x.id===id);if(!g)return;const j=ensureJourney(id),n=goalNarrative(g),linkedMetricIds=[...(j.links.metrics||[])];experiments.filter(x=>ensureImpact(x.id).goalId===id).forEach(x=>(ensureImpact(x.id).metricIds||[]).forEach(m=>{if(!linkedMetricIds.includes(m))linkedMetricIds.push(m)}));const meta=drawerBody.querySelector('.goal-journey-meta');if(meta)meta.insertAdjacentHTML('afterend',`<div class="progress-narrative" style="--journey-accent:${goalShapeCopy(g.kind).accent}"><span>Progress narrative</span><strong>${escapeHTML(n.title)}</strong><p>${escapeHTML(n.copy)}</p>${trendCardsHTML(linkedMetricIds)}</div>`)}
