renderExperiments=function(){renderExperimentsV16Base();const active=experiments.filter(x=>x.status!=='stopped'&&x.status!=='archived');$$('#experimentGrid .experiment-card').forEach(card=>{const exp=experiments.find(x=>x.id===card.dataset.detail);if(!exp)return;const {goal,mets}=impactStatus(exp),review=latestExperimentReview(exp.id),meta=document.createElement('div');meta.className='progress-narrative';meta.style.setProperty('--journey-accent','var(--mint)');meta.innerHTML=`<span>Impact chain</span><strong>${goal?escapeHTML(goal.title):'No goal linked yet'}</strong><p>${mets.length?`${mets.length} signal${mets.length===1?'':'s'} linked`: 'Link one signal that could change the decision.'}${review?` · Last decision: ${escapeHTML(review.decision)}`:''}</p>`;const actions=card.querySelector('.experiment-actions');if(actions)card.insertBefore(meta,actions)});renderImpactSystem();$('#labExperimentCount')&&($('#labExperimentCount').textContent=active.length)}
