function openMetricLog(id){const m=customMetrics.find(x=>x.id===id);if(!m)return;metricLogTarget=id;$('#metricLogTitle').textContent=`Log · ${m.title}`;$('#metricLogCopy').textContent=`Current value: ${m.value||'—'}${m.unit?' '+m.unit:''}. Add a new observation; interpretation stays separate.`;$('#metricLogValue').value='';$('#metricLogModal').classList.add('open');$('#metricLogBackdrop').classList.add('open');setTimeout(()=>$('#metricLogValue').focus(),40)}
