$('#closeMetricLog').onclick=$('#cancelMetricLog').onclick=$('#metricLogBackdrop').onclick=closeMetricLog;
$('#saveMetricLog').onclick=()=>{const m=customMetrics.find(x=>x.id===metricLogTarget),value=$('#metricLogValue').value.trim();if(!m||!value){showToast('Add a value first');return}metricLogs[m.id]=metricLogs[m.id]||[];metricLogs[m.id].push({date:ymd(new Date()),value});m.value=value;store.set('bp-metric-logs-v16',metricLogs);store.set('bp-custom-metrics-v12',customMetrics);closeMetricLog();renderMetrics();renderGoals();showToast('Signal logged')};
document.addEventListener('click',e=>{const log=e.target.closest('[data-log-metric]');if(log){openMetricLog(log.dataset.logMetric);return}const metric=e.target.closest('[data-impact-metric]');if(metric){const imp=ensureImpact(metric.dataset.experimentId),id=metric.dataset.impactMetric,i=imp.metricIds.indexOf(id);i>=0?imp.metricIds.splice(i,1):imp.metricIds.push(id);if(imp.goalId){const j=ensureJourney(imp.goalId);if(!j.links.metrics.includes(id)&&i<0)j.links.metrics.push(id);if(i>=0)j.links.metrics=j.links.metrics.filter(mid=>mid!==id||experiments.some(x=>x.id!==metric.dataset.experimentId&&ensureImpact(x.id).goalId===imp.goalId&&ensureImpact(x.id).metricIds.includes(mid)))}store.set('bp-goal-journeys-v15',goalJourneys);saveImpact();openDrawer(metric.dataset.experimentId);return}const dec=e.target.closest('[data-exp-decision]');if(dec){activeExperimentDecision=dec.dataset.expDecision;$$('[data-exp-decision]',drawerBody).forEach(b=>b.classList.toggle('active',b.dataset.expDecision===activeExperimentDecision));return}const save=e.target.closest('[data-save-experiment-review]');if(save){const exp=experiments.find(x=>x.id===save.dataset.saveExperimentReview);if(!exp)return;const reason=$('#experimentReviewReason').value.trim(),evidence=$('#experimentReviewEvidence').value.trim(),nextAction=$('#experimentNextAction').value.trim();if(!reason){showToast('Add the reason behind the decision');return}const row={id:'exp-review-'+Date.now(),experimentId:exp.id,experimentTitle:exp.title,decision:activeExperimentDecision,reason,evidence,nextAction,date:ymd(new Date()),createdAt:new Date().toISOString()};experimentReviews.push(row);if(activeExperimentDecision==='stop')exp.status='stopped';else exp.status='active';store.set('bp-experiment-reviews-v16',experimentReviews);store.set('bp-experiments-v5',experiments);if(nextAction&&$('#experimentPinNext').checked){inbox.push({title:nextAction,meta:`Experiment review · ${exp.title}`,type:'Next action'});store.set('bp-inbox-v2',inbox);renderInbox()}renderExperiments();renderImpactSystem();openDrawer(exp.id);showToast(`${activeExperimentDecision[0].toUpperCase()+activeExperimentDecision.slice(1)} decision saved`);return}})
document.addEventListener('change',e=>{if(e.target.id==='impactGoalSelect'){const expId=e.target.dataset.experimentId,imp=ensureImpact(expId),old=imp.goalId;imp.goalId=e.target.value;if(old){const oldJ=ensureJourney(old);oldJ.links.experiments=oldJ.links.experiments.filter(id=>id!==expId)}if(imp.goalId){const j=ensureJourney(imp.goalId);if(!j.links.experiments.includes(expId))j.links.experiments.push(expId);imp.metricIds.forEach(id=>{if(!j.links.metrics.includes(id))j.links.metrics.push(id)})}store.set('bp-goal-journeys-v15',goalJourneys);saveImpact();openDrawer(expId);showToast('Impact goal updated')}})
